        "content": "import java.util.*;\n\nabstract class ContentUnit {\n    protected String title;\n\n    public ContentUnit(String title) {\n        this.title = title;\n    }\n\n    public String getTitleTag() {\n        return \"[\" + title.trim() + \"]\";\n    }\n\n    public abstract int measure();\n\n    public abstract String getStatus();\n\n    public String describe() {\n        return getTitleTag() + \" | measure=\" + measure() + \" | \" + getStatus();\n    }\n}\n\nclass ParagraphUnit extends ContentUnit {\n    private String content;\n\n    public ParagraphUnit(String title, String content) {\n        super(title);\n        this.content = content;\n    }\n\n    @Override\n    public int measure() {\n        return content.trim().length();\n    }\n\n    @Override\n    public String getStatus() {\n        return content.trim().isEmpty() ? \"EMPTY\" : \"READY\";\n    }\n}\n\nclass SlideUnit extends ContentUnit {\n    private int pageCount;\n\n    public SlideUnit(String title, int pageCount) {\n        super(title);\n        this.pageCount = pageCount;\n    }\n\n    @Override\n    public int measure() {\n        return pageCount;\n    }\n\n    @Override\n    public String getStatus() {\n        return pageCount < 5 ? \"SHORT\" : \"FULL\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String paragraphTitle = sc.nextLine();\n        String paragraphContent = sc.nextLine();\n        String slideTitle = sc.nextLine();\n        int pageCount = Integer.parseInt(sc.nextLine());\n\n        ContentUnit[] units = new ContentUnit[] {\n            new ParagraphUnit(paragraphTitle, paragraphContent),\n            new SlideUnit(slideTitle, pageCount)\n        };\n\n        for (ContentUnit unit : units) {\n            System.out.println(unit.describe());\n        }\n    }\n}\n"
