        "content": "import java.util.*;\n\nabstract class NumberChecker {\n    public abstract boolean check(int value);\n\n    public int countPassed(int[] values) {\n        int count = 0;\n        for (int value : values) {\n            if (check(value)) {\n                count++;\n            }\n        }\n        return count;\n    }\n\n    public int firstPassed(int[] values) {\n        for (int value : values) {\n            if (check(value)) {\n                return value;\n            }\n        }\n        return -1;\n    }\n}\n\nclass PositiveChecker extends NumberChecker {\n    @Override\n    public boolean check(int value) {\n        return value > 0;\n    }\n}\n\nclass DivisibleChecker extends NumberChecker {\n    private int divisor;\n\n    public DivisibleChecker(int divisor) {\n        this.divisor = divisor;\n    }\n\n    @Override\n    public boolean check(int value) {\n        return value % divisor == 0;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] values = new int[n];\n        for (int i = 0; i < n; i++) {\n            values[i] = sc.nextInt();\n        }\n        int divisor = sc.nextInt();\n\n        NumberChecker checker1 = new PositiveChecker();\n        NumberChecker checker2 = new DivisibleChecker(divisor);\n\n        System.out.println(checker1.countPassed(values));\n        System.out.println(checker1.firstPassed(values));\n        System.out.println(checker2.countPassed(values));\n        System.out.println(checker2.firstPassed(values));\n    }\n}\n"
