        "content": "import java.util.*;\n\nabstract class TaskProcessor {\n    protected int remainingTasks;\n    protected int processedTasks;\n\n    public TaskProcessor(int initialTasks) {\n        this.remainingTasks = initialTasks;\n        this.processedTasks = 0;\n    }\n\n    public abstract void processOneCycle();\n\n    public void addTasks(int count) {\n        if (count > 0) {\n            remainingTasks += count;\n        }\n    }\n\n    public void run(int cycles) {\n        if (cycles <= 0) {\n            return;\n        }\n        for (int i = 0; i < cycles; i++) {\n            processOneCycle();\n        }\n    }\n\n    public int getRemainingTasks() {\n        return remainingTasks;\n    }\n\n    public int getProcessedTasks() {\n        return processedTasks;\n    }\n}\n\nclass StandardProcessor extends TaskProcessor {\n    private int capacity;\n\n    public StandardProcessor(int initialTasks, int capacity) {\n        super(initialTasks);\n        this.capacity = capacity;\n    }\n\n    @Override\n    public void processOneCycle() {\n        if (capacity <= 0 || remainingTasks <= 0) {\n            return;\n        }\n        int processedNow = Math.min(capacity, remainingTasks);\n        remainingTasks -= processedNow;\n        processedTasks += processedNow;\n    }\n}\n\nclass BurstProcessor extends TaskProcessor {\n    private int capacity;\n    private int cycleCount;\n\n    public BurstProcessor(int initialTasks, int capacity) {\n        super(initialTasks);\n        this.capacity = capacity;\n        this.cycleCount = 0;\n    }\n\n    @Override\n    public void processOneCycle() {\n        cycleCount++;\n        if (capacity <= 0 || remainingTasks <= 0) {\n            return;\n        }\n\n        int currentCapacity;\n        if (cycleCount % 2 == 1) {\n            currentCapacity = capacity;\n        } else {\n            currentCapacity = capacity + 1;\n        }\n\n        int processedNow = Math.min(currentCapacity, remainingTasks);\n 