        "content": "import java.util.*;\n\nabstract class Evaluation {\n    protected String courseName;\n\n    public Evaluation(String courseName) {\n        this.courseName = courseName;\n    }\n\n    public abstract String getLevel();\n    public abstract boolean isPassed();\n\n    public String buildReport(String studentName) {\n        return courseName + \": \" + studentName + \" - \" + getLevel() + \" - \" + (isPassed() ? \"Pass\" : \"Fail\");\n    }\n}\n\nclass ScoreEvaluation extends Evaluation {\n    private String studentName;\n    private int score;\n\n    public ScoreEvaluation(String courseName, String studentName, int score) {\n        super(courseName);\n        this.studentName = studentName;\n        this.score = score;\n    }\n\n    @Override\n    public String getLevel() {\n        if (score >= 85) {\n            return \"Excellent\";\n        } else if (score >= 70) {\n            return \"Good\";\n        } else if (score >= 50) {\n            return \"Average\";\n        }\n        return \"Needs Improvement\";\n    }\n\n    @Override\n    public boolean isPassed() {\n        return score >= 50;\n    }\n\n    public String getReport() {\n        return buildReport(studentName);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String courseName = sc.next();\n        String studentName = sc.next();\n        int score = sc.nextInt();\n\n        ScoreEvaluation evaluation = new ScoreEvaluation(courseName, studentName, score);\n        System.out.println(evaluation.getReport());\n    }\n}\n"
