        "content": "import java.util.*;\n\nabstract class TextRule {\n    protected String text;\n\n    public TextRule(String text) {\n        this.text = text;\n    }\n\n    public int countLetters() {\n        int count = 0;\n        for (int i = 0; i < text.length(); i++) {\n            if (Character.isLetter(text.charAt(i))) {\n                count++;\n            }\n        }\n        return count;\n    }\n\n    public abstract String transform();\n}\n\nclass CompactText extends TextRule {\n    public CompactText(String text) {\n        super(text);\n    }\n\n    @Override\n    public String transform() {\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < text.length(); i++) {\n            char c = text.charAt(i);\n            if (c != ' ') {\n                sb.append(c);\n            }\n        }\n        return sb.toString();\n    }\n}\n\nclass MirrorText extends TextRule {\n    public MirrorText(String text) {\n        super(text);\n    }\n\n    @Override\n    public String transform() {\n        StringBuilder sb = new StringBuilder(text);\n        return sb.reverse().toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String type = sc.nextLine().trim();\n        String text = sc.nextLine();\n\n        TextRule rule;\n        if (type.equals(\"compact\")) {\n            rule = new CompactText(text);\n        } else {\n            rule = new MirrorText(text);\n        }\n\n        System.out.println(rule.transform());\n        System.out.println(rule.countLetters());\n    }\n}\n"
