        "filename": "Main.java",
        "content": "import java.util.*;\n\nabstract class Evaluation {\n    protected String name;\n    protected int score;\n\n    public Evaluation(String name, int score) {\n        this.name = name;\n        this.score = score;\n    }\n\n    public abstract String getResult();\n\n    public String getSummary() {\n        return name + \":\" + getResult();\n    }\n}\n\nclass PassFailEvaluation extends Evaluation {\n    public PassFailEvaluation(String name, int score) {\n        super(name, score);\n    }\n\n    @Override\n    public String getResult() {\n        if (score >= 50) {\n            return \"PASS\";\n        }\n        return \"FAIL\";\n    }\n}\n\nclass LetterEvaluation extends Evaluation {\n    public LetterEvaluation(String name, int score) {\n        super(name, score);\n    }\n\n    @Override\n    public String getResult() {\n        if (score >= 85) {\n            return \"A\";\n        } else if (score >= 70) {\n            return \"B\";\n        } else if (score >= 50) {\n            return \"C\";\n        }\n        return \"F\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        Evaluation[] evaluations = new Evaluation[2];\n\n        for (int i = 0; i < 2; i++) {\n            String type = sc.next();\n            String name = sc.next();\n            int score = sc.nextInt();\n\n            if (type.equals(\"PF\")) {\n                evaluations[i] = new PassFailEvaluation(name, score);\n            } else {\n                evaluations[i] = new LetterEvaluation(name, score);\n            }\n        }\n\n        for (Evaluation e : evaluations) {\n            System.out.println(e.getSummary());\n        }\n    }\n}\n"
