        "content": "import java.util.*;\n\nabstract class NumberSequence {\n    protected int start;\n    protected int end;\n\n    public NumberSequence(int start, int end) {\n        this.start = start;\n        this.end = end;\n    }\n\n    public abstract String buildSequence();\n\n    public String getDescription() {\n        return buildSequence();\n    }\n}\n\nclass EvenSequence extends NumberSequence {\n    public EvenSequence(int start, int end) {\n        super(start, end);\n    }\n\n    @Override\n    public String buildSequence() {\n        if (start > end) {\n            return \"empty\";\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = start; i <= end; i++) {\n            if (i % 2 == 0) {\n                if (sb.length() > 0) {\n                    sb.append(\" \");\n                }\n                sb.append(i);\n            }\n        }\n\n        if (sb.length() == 0) {\n            return \"empty\";\n        }\n        return sb.toString();\n    }\n}\n\nclass OddSequence extends NumberSequence {\n    public OddSequence(int start, int end) {\n        super(start, end);\n    }\n\n    @Override\n    public String buildSequence() {\n        if (start > end) {\n            return \"empty\";\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = start; i <= end; i++) {\n            if (i % 2 != 0) {\n                if (sb.length() > 0) {\n                    sb.append(\" \");\n                }\n                sb.append(i);\n            }\n        }\n\n        if (sb.length() == 0) {\n            return \"empty\";\n        }\n        return sb.toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        NumberSequence[] sequences = new NumberSequence[n];\n\n        for (int i = 0; i < n; i++) {\n            String type = sc.next();\n            int start = sc.nextInt();\n 