        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Member {\n    private String name;\n\n    public Member(String name) {\n        this.name = name;\n    }\n\n    public int getNameLength() {\n        return name.length();\n    }\n}\n\nclass PremiumMember extends Member {\n    private int bonus;\n\n    public PremiumMember(String name, int bonus) {\n        super(name);\n        this.bonus = bonus;\n    }\n\n    public int getTotalScore() {\n        return getNameLength() + bonus;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String name = sc.next();\n        int bonus = sc.nextInt();\n\n        PremiumMember member = new PremiumMember(name, bonus);\n        System.out.println(member.getNameLength());\n        System.out.println(member.getTotalScore());\n    }\n}\n"
