        "content": "import java.util.*;\n\nclass IndexedWordList {\n    private List<String> words;\n\n    public IndexedWordList(List<String> words) {\n        this.words = words;\n    }\n\n    public String getWordAt(int index) {\n        return words.get(index);\n    }\n\n    public int findFirst(String target) {\n        return words.indexOf(target);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> data = new ArrayList<>();\n        for (int i = 0; i < n; i++) {\n            data.add(sc.next());\n        }\n        int index = sc.nextInt();\n        String target = sc.next();\n\n        IndexedWordList list = new IndexedWordList(data);\n        System.out.println(list.getWordAt(index));\n        System.out.println(list.findFirst(target));\n    }\n}\n"
