        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Playlist {\n    private List<String> songs;\n\n    public Playlist(List<String> songs) {\n        this.songs = songs;\n    }\n\n    public String getSongAt(int index) {\n        if (index < 0 || index >= songs.size()) {\n            return \"Invalid index\";\n        }\n        return songs.get(index);\n    }\n\n    public int findSong(String title) {\n        return songs.indexOf(title);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> songs = new ArrayList<>();\n\n        for (int i = 0; i < n; i++) {\n            songs.add(sc.next());\n        }\n\n        int index = sc.nextInt();\n        String target = sc.next();\n\n        Playlist playlist = new Playlist(songs);\n        System.out.println(playlist.getSongAt(index));\n        System.out.println(playlist.findSong(target));\n    }\n}\n"
