        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass ListTool {\n    public String analyze(List<String> items, String target) {\n        int firstIndex = -1;\n        int count = 0;\n\n        for (int i = 0; i < items.size(); i++) {\n            if (items.get(i).equals(target)) {\n                if (firstIndex == -1) {\n                    firstIndex = i;\n                }\n                count++;\n            }\n        }\n\n        return firstIndex + \" \" + count;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> items = new ArrayList<>();\n\n        for (int i = 0; i < n; i++) {\n            items.add(sc.next());\n        }\n\n        String target = sc.next();\n        ListTool tool = new ListTool();\n        System.out.println(tool.analyze(items, target));\n    }\n}\n"
      }
