    "skeleton_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass ListEditor {\n    public String insertAndFormat(List<String> items, int index, String value) {\n        return \"\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> items = new ArrayList<>();\n        for (int i = 0; i < n; i++) {\n            items.add(sc.next());\n        }\n        int index = sc.nextInt();\n        String value = sc.next();\n\n        ListEditor editor = new ListEditor();\n        System.out.println(editor.insertAndFormat(items, index, value));\n    }\n}\n",
        "is_readonly": false
