        "filename": "main.c",
        "content": "#include <stdio.h>\n\nint main(void) {\n    int x, a, b;\n    int *p;\n    int **pp;\n\n    scanf(\"%d %d %d\", &x, &a, &b);\n\n    p = &x;\n    pp = &p;\n\n    *p = *p + a;\n    printf(\"%d\\n\", x);\n\n    **pp = **pp + b;\n    printf(\"%d\\n\", x);\n\n    return 0;\n}\n"
      }
