        "content": "#include <stdio.h>\n\nint main(void) {\n    char names[5][31];\n    int start, end;\n    int i;\n\n    for (i = 0; i < 5; i++) {\n        scanf(\"%30s\", names[i]);\n    }\n    scanf(\"%d %d\", &start, &end);\n\n    if (start < 1 || start > 5 || end < 1 || end > 5 || start > end) {\n        printf(\"INVALID\\n\");\n    } else {\n        for (i = start - 1; i <= end - 1; i++) {\n            printf(\"%d: %s\\n\", i + 1, names[i]);\n        }\n    }\n\n    return 0;\n}\n"
