        "filename": "Main.java",
        "content": "import java.util.*;\n\ninterface WordList {\n    void add(String word);\n    void add(int index, String word);\n    String get(int index);\n    int indexOf(String word);\n    int size();\n}\n\nclass BasicWordList implements WordList {\n    private String[] data;\n    private int count;\n\n    public BasicWordList() {\n        data = new String[20];\n        count = 0;\n    }\n\n    @Override\n    public void add(String word) {\n        data[count] = word;\n        count++;\n    }\n\n    @Override\n    public void add(int index, String word) {\n        for (int i = count; i > index; i--) {\n            data[i] = data[i - 1];\n        }\n        data[index] = word;\n        count++;\n    }\n\n    @Override\n    public String get(int index) {\n        return data[index];\n    }\n\n    @Override\n    public int indexOf(String word) {\n        for (int i = 0; i < count; i++) {\n            if (data[i].equals(word)) {\n                return i;\n            }\n        }\n        return -1;\n    }\n\n    @Override\n    public int size() {\n        return count;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        String w1 = sc.next();\n        String w2 = sc.next();\n        String w3 = sc.next();\n        int insertIndex = sc.nextInt();\n        String insertedWord = sc.next();\n        String searchWord = sc.next();\n\n        WordList list = new BasicWordList();\n        list.add(w1);\n        list.add(w2);\n        list.add(w3);\n        list.add(insertIndex, insertedWord);\n\n        System.out.println(list.size());\n        System.out.println(list.get(0));\n        System.out.println(list.get(insertIndex));\n        System.out.println(list.indexOf(searchWord));\n    }\n}\n"
