        "filename": "Main.java",
        "content": "import java.util.*;\n\ninterface Playlist {\n    void addSong(String title);\n    void insertSong(int index, String title);\n    String getSong(int index);\n    int indexOfSong(String title);\n    int size();\n}\n\nclass SimplePlaylist implements Playlist {\n    private List<String> songs;\n\n    public SimplePlaylist() {\n        songs = new ArrayList<>();\n    }\n\n    @Override\n    public void addSong(String title) {\n        songs.add(title);\n    }\n\n    @Override\n    public void insertSong(int index, String title) {\n        songs.add(index, title);\n    }\n\n    @Override\n    public String getSong(int index) {\n        return songs.get(index);\n    }\n\n    @Override\n    public int indexOfSong(String title) {\n        return songs.indexOf(title);\n    }\n\n    @Override\n    public int size() {\n        return songs.size();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        String s1 = sc.nextLine();\n        String s2 = sc.nextLine();\n        String s3 = sc.nextLine();\n        int insertIndex = Integer.parseInt(sc.nextLine());\n        String insertedSong = sc.nextLine();\n        String searchSong = sc.nextLine();\n\n        Playlist playlist = new SimplePlaylist();\n        playlist.addSong(s1);\n        playlist.addSong(s2);\n        playlist.addSong(s3);\n        playlist.insertSong(insertIndex, insertedSong);\n\n        System.out.println(playlist.size());\n        System.out.println(playlist.getSong(0));\n        System.out.println(playlist.getSong(insertIndex));\n        System.out.println(playlist.indexOfSong(searchSong));\n    }\n}\n"
