        "filename": "Main.java",
        "content": "import java.util.*;\n\nabstract class Member {\n    protected int lateDays;\n\n    public Member(int lateDays) {\n        this.lateDays = lateDays;\n    }\n\n    public abstract int getFine();\n}\n\nclass StudentMember extends Member {\n    public StudentMember(int lateDays) {\n        super(lateDays);\n    }\n\n    @Override\n    public int getFine() {\n        if (lateDays <= 3) {\n            return 0;\n        }\n        return (lateDays - 3) * 2000;\n    }\n}\n\nclass TeacherMember extends Member {\n    public TeacherMember(int lateDays) {\n        super(lateDays);\n    }\n\n    @Override\n    public int getFine() {\n        if (lateDays <= 5) {\n            return 0;\n        }\n        return (lateDays - 5) * 1000;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int studentLateDays = sc.nextInt();\n        int teacherLateDays = sc.nextInt();\n\n        Member student = new StudentMember(studentLateDays);\n        Member teacher = new TeacherMember(teacherLateDays);\n\n        System.out.println(student.getFine());\n        System.out.println(teacher.getFine());\n    }\n}\n"
      }
