        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        int[] queue = new int[n];\n        int f = 0;\n        int l = -1;\n        int size = 0;\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n\n            if (parts[0].equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                if (size == n) {\n                    System.out.println(\"FULL\");\n                } else {\n                    l = (l + 1) % n;\n                    queue[l] = x;\n                    size++;\n                }\n            } else if (parts[0].equals(\"DEQ\")) {\n                if (size == 0) {\n                    System.out.println(\"EMPTY\");\n                } else {\n                    f = (f + 1) % n;\n                    size--;\n                    if (size == 0) {\n                        f = 0;\n                        l = -1;\n                    }\n                }\n            } else if (parts[0].equals(\"FRONT\")) {\n                if (size == 0) {\n                    System.out.println(\"EMPTY\");\n                } else {\n                    System.out.println(queue[f]);\n                }\n            }\n        }\n    }\n}\n"
