        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        int f = sc.nextInt();\n        int l = sc.nextInt();\n        int d = sc.nextInt();\n        int e = sc.nextInt();\n\n        f = (f + d) % N;\n        l = (l + e) % N;\n\n        System.out.println(f + \" \" + l);\n    }\n}\n"
