        "content": "import java.util.*;\n\nclass Person {\n    protected String name;\n\n    public Person(String name) {\n        this.name = name;\n    }\n\n    public String getName() {\n        return name;\n    }\n}\n\nclass Professor extends Person {\n    private String department;\n    private Student[] students;\n    private int count;\n\n    public Professor(String name, String department, int capacity) {\n        super(name);\n        this.department = department;\n        this.students = new Student[capacity];\n        this.count = 0;\n    }\n\n    public String getDepartment() {\n        return department;\n    }\n\n    public void addStudent(Student s) {\n        if (s != null && count < students.length) {\n            students[count] = s;\n            count++;\n            s.setProfessor(this);\n        }\n    }\n}\n\nclass Student extends Person {\n    private String studentId;\n    private Professor pr;\n\n    public Student(String name, String studentId) {\n        super(name);\n        this.studentId = studentId;\n        this.pr = null;\n    }\n\n    public String getStudentId() {\n        return studentId;\n    }\n\n    public void setProfessor(Professor pr) {\n        this.pr = pr;\n    }\n\n    public String getProfessorDepartment() {\n        if (pr == null) {\n            return \"None\";\n        }\n        return pr.getDepartment();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        String professorName = sc.nextLine();\n        String department = sc.nextLine();\n        int n = Integer.parseInt(sc.nextLine());\n\n        Professor professor = new Professor(professorName, department, n);\n        Student[] arr = new Student[n];\n\n        for (int i = 0; i < n; i++) {\n            String studentName = sc.nextLine();\n            String studentId = sc.nextLine();\n            arr[i] = new Student(studentName, studentId);\n            professor.addStudent(arr[i]);\n        }\n\n        for (Student s : arr) {\n            System.out.println(s.getName() + \"-\" + s.getStudentId() + \"-\" + s.getProfessorDepartment());\n        }\n    }\n}\n"
