        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static int reachableCount(int M, int x) {\n        boolean[] visited = new boolean[M];\n        int h = x % M;\n        int i = 0;\n        int count = 0;\n\n        while (true) {\n            int pos = (h + i * i) % M;\n            if (visited[pos]) {\n                break;\n            }\n            visited[pos] = true;\n            count++;\n            i++;\n        }\n\n        return count;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int q = sc.nextInt();\n\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < q; i++) {\n            int x = sc.nextInt();\n            if (i > 0) out.append(\" \");\n            out.append(reachableCount(M, x));\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
