        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int h = sc.nextInt();\n        int target = sc.nextInt();\n\n        // Write your code here\n    }\n}\n",
        "is_readonly": false
      }
    ],
    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int h = sc.nextInt();\n        int target = sc.nextInt();\n\n        boolean[] visited = new boolean[M];\n        int countDistinct = 0;\n\n        for (int i = 0; ; i++) {\n            int pos = (h + i * i) % M;\n\n            if (visited[pos]) {\n                System.out.println(\"NOT_FOUND \" + countDistinct);\n                return;\n            }\n\n            visited[pos] = true;\n            countDistinct++;\n\n            if (pos == target) {\n                System.out.println(\"FOUND \" + i);\n                return;\n            }\n        }\n    }\n}\n"
      }
    ],
