nteger val = q.dequeue();\n                out.append(val == null ? \"EMPTY\" : val).append('\\n');\n            } else if (cmd.equals(\"FRONT\")) {\n                Integer val = q.front();\n                out.append(val == null ? \"EMPTY\" : val).append('\\n');\n            } else if (cmd.equals(\"EMPTY\")) {\n                out.append(q.isEmpty()).append('\\n');\n            } else if (cmd.equals(\"FULL\")) {\n                out.append(q.isFull()).append('\\n');\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
