        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        int[] a = new int[n];\n        int first = -1, last = -1;\n\n        for (int k = 0; k < m; k++) {\n            String op = sc.next();\n\n            if (op.equals(\"ADD\")) {\n                int x = sc.nextInt();\n                if (last == n - 1 || last == -1) {\n                    a[0] = x;\n                    last = 0;\n                    if (first == -1) first = 0;\n                } else {\n                    a[++last] = x;\n                    if (first == -1) first = 0;\n                }\n            } else if (op.equals(\"TAKE\")) {\n                if (first == last) {\n                    first = last = -1;\n                } else if (first == n - 1) {\n                    first = 0;\n                } else {\n                    first++;\n                }\n            }\n        }\n\n        System.out.println(first + \" \" + last);\n\n        if (first == -1) {\n            System.out.println(\"EMPTY\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(\" \");\n                if (i == n - 1) i = 0;\n                else i++;\n            }\n            System.out.println(sb.toString());\n        }\n    }\n}\n"
