        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        int[] a;\n        int max;\n        int first, last;\n\n        CircularQueue(int max) {\n            this.max = max;\n            this.a = new int[max];\n            this.first = -1;\n            this.last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        void enqueue(int x) {\n            if (last == max - 1 || last == -1) {\n                a[0] = x;\n                last = 0;\n                if (first == -1) first = 0;\n            } else {\n                a[++last] = x;\n            }\n        }\n\n        Integer dequeue() {\n            if (isEmpty()) return null;\n            int x = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return x;\n        }\n\n        Integer front() {\n            if (isEmpty()) return null;\n            return a[first];\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue q = new CircularQueue(m);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < n; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n            String cmd = parts[0];\n\n            if (cmd.equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                if (q.isFull()) {\n                    out.append(\"FULL\\n\");\n                } else {\n                    q.enqueue(x);\n                }\n            } else if (cmd.equals(\"DEQ\")) {\n                Integer val = q.dequeue();\n                if (val == null) out.append(\"EMPTY\\n\");\n                else out.append(val).append('\\n');\n            } else if (cmd.equals(\"FRONT\")) {\n                Integer val = q.front();\n                if (val == null) out.append(\"EMPTY\\n\");\n                else out.append(val).append('\\n');\n            } else if (cmd.equals(\"ISEMPTY\")) {\n                out.append(q.isEmpty()).append('\\n');\n            } else if (cmd.equals(\"ISFULL\")) {\n                out.append(q.isFull()).append('\\n');\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
