        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        int[] a = new int[m];\n        int first = -1;\n        int last = -1;\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n\n            if (line.startsWith(\"ENQ\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n\n                boolean isFull = (first == 0 && last == m - 1) || (first == last + 1);\n                if (isFull) {\n                    continue;\n                }\n\n                if (last == m - 1 || last == -1) {\n                    a[0] = x;\n                    last = 0;\n                    if (first == -1) {\n                        first = 0;\n                    }\n                } else {\n                    a[++last] = x;\n                    if (first == -1) {\n                        first = 0;\n                    }\n                }\n            } else if (line.equals(\"DEQ\")) {\n                if (first == -1) {\n                    System.out.println(-1);\n                } else {\n                    int x = a[first];\n                    System.out.println(x);\n\n                    if (first == last) {\n                        first = last = -1;\n                    } else if (first == m - 1) {\n                        first = 0;\n                    } else {\n                        first++;\n                    }\n                }\n            } else if (line.equals(\"FRONT\")) {\n                if (first == -1) {\n                    System.out.println(-1);\n                } else {\n                    System.out.println(a[first]);\n                }\n            }\n        }\n    }\n}\n"
