        "content": "import java.util.*;\n\nclass IntQueue {\n    private int[] a;\n    private int max;\n    private int first, last;\n\n    public IntQueue(int capacity) {\n        max = capacity;\n        a = new int[max];\n        first = last = -1;\n    }\n\n    public boolean isEmpty() {\n        return first == -1;\n    }\n\n    public boolean isFull() {\n        return (first == 0 && last == max - 1) || first == last + 1;\n    }\n\n    private boolean grow() {\n        int newMax = max + max / 2;\n        if (newMax <= max) newMax = max + 1;\n\n        int[] b = new int[newMax];\n\n        // copy current queue to b so that the front element becomes b[0]\n\n        a = b;\n        max = newMax;\n        return true;\n    }\n\n    public void add(int x) {\n        if (isFull() && !grow()) return;\n\n        if (last == max - 1 || last == -1) {\n            a[0] = x;\n            last = 0;\n            if (first == -1) first = 0;\n        } else {\n            a[++last] = x;\n        }\n    }\n\n    public int peek() {\n        if (isEmpty()) return -1;\n        return a[first];\n    }\n\n    public int take() {\n        if (isEmpty()) return -1;\n\n        int x = a[first];\n\n        if (first == last) {\n            first = last = -1;\n        } else if (first == max - 1) {\n            first = 0;\n        } else {\n            first++;\n        }\n\n        return x;\n    }\n\n    public String finalOrder() {\n        if (isEmpty()) return \"EMPTY\";\n\n        StringBuilder sb = new StringBuilder();\n\n        // build values from front to rear in logical queue order\n\n        return sb.toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        IntQueue queue = new IntQueue(m);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n\n            if (parts[0].equals(\"ADD\")) {\n                int x = Integer.parseInt(parts[1]);\n                queue.add(x);\n            } else if (parts[0].equals(\"TAKE\")) {\n                out.append(queue.take()).append('\\n');\n            } else if (parts[0].equals(\"PEEK\")) {\n                out.append(queue.peek()).append('\\n');\n            }\n        }\n\n        out.append(queue.finalOrder());\n        System.out.print(out.toString());\n    }\n}\n",
