        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        int[] a;\n        int max;\n        int first;\n        int last;\n\n        CircularQueue(int capacity) {\n            max = capacity;\n            a = new int[max];\n            first = -1;\n            last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        void arrive(int x) {\n            if (last == max - 1 || last == -1) {\n                a[0] = x;\n                last = 0;\n                if (first == -1) first = 0;\n            } else {\n                a[++last] = x;\n            }\n        }\n\n        int next() throws Exception {\n            if (isEmpty()) throw new Exception();\n            return a[first];\n        }\n\n        int serve() throws Exception {\n            if (isEmpty()) throw new Exception();\n            int x = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return x;\n        }\n\n        String snapshot() {\n            if (isEmpty()) return \"EMPTY\";\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                if (sb.length() > 0) sb.append(' ');\n                sb.append(a[i]);\n                if (i == last) break;\n                if (i == max - 1) i = 0;\n                else i++;\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue queue = new CircularQueue(n);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n         