        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int cap = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        int[] a = new int[cap];\n        int first = -1;\n        int last = -1;\n\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n            String cmd = parts[0];\n\n            boolean isEmpty = (first == -1);\n            boolean isFull = ((first == 0 && last == cap - 1) || first == last + 1);\n\n            if (cmd.equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                if (isFull) {\n                    out.append(\"FULL\\n\");\n                } else {\n                    if (last == cap - 1 || last == -1) {\n                        a[0] = x;\n                        last = 0;\n                        if (first == -1) first = 0;\n                    } else {\n                        a[++last] = x;\n                    }\n                }\n            } else if (cmd.equals(\"FRONT\")) {\n                if (isEmpty) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(a[first]).append('\\n');\n                }\n            } else if (cmd.equals(\"DEQ\")) {\n                if (isEmpty) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    int x = a[first];\n                    if (first == last) {\n                        first = last = -1;\n                    } else if (first == cap - 1) {\n                        first = 0;\n                    } else {\n                        first++;\n                    }\n                    out.append(x).append('\\n');\n                }\n            }\n        }\n\n        if (first == -1) {\n            out.append(\"EMPTY\");\n        } else {\n            int i = first;\n            while (true) {\n                out.append(a[i]);\n                if (i == last) break;\n                out.append(' ');\n                if (i == cap - 1) i = 0;\n                else i++;\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
