        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        int[] a;\n        int max;\n        int first;\n        int last;\n\n        CircularQueue(int capacity) {\n            max = capacity;\n            a = new int[max];\n            first = -1;\n            last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        void add(int x) {\n            if (isFull()) return;\n            if (last == max - 1 || last == -1) {\n                a[0] = x;\n                last = 0;\n                if (first == -1) first = 0;\n            } else {\n                a[++last] = x;\n            }\n        }\n\n        int see() {\n            if (isEmpty()) return -1;\n            return a[first];\n        }\n\n        int take() {\n            if (isEmpty()) return -1;\n            int x = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return x;\n        }\n\n        String remaining() {\n            if (isEmpty()) return \"EMPTY\";\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(' ');\n                if (i == max - 1) i = 0;\n                else i++;\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int capacity = sc.nextInt();\n        int n = sc.nextInt();\n\n        CircularQueue q = new CircularQueue(capacity);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < n; i++) {\n     