        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        int[] a = new int[m];\n        int first = -1;\n        int last = -1;\n\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < n; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n\n            if (parts[0].equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                boolean isFull = (first == 0 && last == m - 1) || (first == last + 1);\n\n                if (isFull) {\n                    out.append(\"FULL\\n\");\n                } else {\n                    if (last == m - 1 || last == -1) {\n                        a[0] = x;\n                        last = 0;\n                        if (first == -1) {\n                            first = 0;\n                        }\n                    } else {\n                        a[++last] = x;\n                    }\n                }\n            } else if (parts[0].equals(\"DEQ\")) {\n                if (first == -1) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    int x = a[first];\n                    out.append(x).append('\\n');\n\n                    if (first == last) {\n                        first = last = -1;\n                    } else if (first == m - 1) {\n                        first = 0;\n                    } else {\n                        first++;\n                    }\n                }\n            } else if (parts[0].equals(\"FRONT\")) {\n                if (first == -1) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(a[first]).append('\\n');\n                }\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
