        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        int[] a = new int[m];\n        int first = -1;\n        int last = -1;\n\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < n; i++) {\n            String line = sc.nextLine().trim();\n\n            if (line.startsWith(\"ADD\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n\n                boolean full = (first == 0 && last == m - 1) || (first == last + 1);\n                if (full) {\n                    out.append(\"FULL\\n\");\n                } else {\n                    if (last == m - 1 || last == -1) {\n                        a[0] = x;\n                        last = 0;\n                        if (first == -1) {\n                            first = 0;\n                        }\n                    } else {\n                        a[++last] = x;\n                    }\n                }\n            } else if (line.equals(\"SERVE\")) {\n                if (first == -1) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    int x = a[first];\n                    out.append(x).append('\\n');\n                    if (first == last) {\n                        first = last = -1;\n                    } else if (first == m - 1) {\n                        first = 0;\n                    } else {\n                        first++;\n                    }\n                }\n            } else if (line.equals(\"CHECK\")) {\n                if (first == -1) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(a[first]).append('\\n');\n                }\n            }\n        }\n\n        if (first == -1) {\n            out.append(\"EMPTY\");\n        } else {\n            int i = first;\n            while (true) {\n                out.append(a[i]);\n                if (i == last) break;\n                out.append(' ');\n                if (i == m - 1) i = 0;\n                else i++;\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
