ringBuilder();\n        int n = size();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(' ');\n            sb.append(a[(first + i) % max]);\n        }\n        return sb.toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int capacity = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue q = new CircularQueue(capacity);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ADD\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n                q.add(x);\n            } else if (line.equals(\"SERVE\")) {\n                Integer val = q.serve();\n                out.append(val == null ? \"EMPTY\" : val).append('\\n');\n            } else if (line.equals(\"CHECK\")) {\n                Integer val = q.check();\n                out.append(val == null ? \"EMPTY\" : val).append('\\n');\n            }\n        }\n\n        out.append(q.snapshot());\n        System.out.print(out.toString());\n    }\n}\n"
