        "content": "import java.util.*;\n\npublic class Main {\n    static class ArrayQueue {\n        int[] a;\n        int max;\n        int first, last;\n\n        ArrayQueue(int max) {\n            this.max = max;\n            a = new int[max];\n            first = last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        boolean enqueue(int x) {\n            if (isFull()) return false;\n            if (last == max - 1 || last == -1) {\n                a[0] = x;\n                last = 0;\n                if (first == -1) first = 0;\n            } else {\n                a[++last] = x;\n            }\n            return true;\n        }\n\n        Integer front() {\n            if (isEmpty()) return null;\n            return a[first];\n        }\n\n        Integer dequeue() {\n            if (isEmpty()) return null;\n            int x = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return x;\n        }\n\n        String content() {\n            if (isEmpty()) return \"EMPTY\";\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                if (sb.length() > 0) sb.append(' ');\n                sb.append(a[i]);\n                if (i == last) break;\n                if (i == max - 1) i = 0;\n                else i++;\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int max = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        ArrayQueue q = new ArrayQueue(max);\n\n        for (int i = 0; i < n; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n\n            if (parts[0].equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                if (!q.enqueue(x)) {\n                    System.out.println(\"FULL\");\n                }\n            } else if (parts[0].equals(\"DEQ\")) {\n                Integer v = q.dequeue();\n                if (v == null) System.out.println(\"EMPTY\");\n                else System.out.println(v);\n            } else if (parts[0].equals(\"FRONT\")) {\n                Integer v = q.front();\n                if (v == null) System.out.println(\"EMPTY\");\n                else System.out.println(v);\n            }\n        }\n\n        System.out.println(q.content());\n    }\n}\n"
