        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        int[] a;\n        int max;\n        int first;\n        int last;\n\n        CircularQueue(int capacity) {\n            max = capacity;\n            a = new int[max];\n            first = -1;\n            last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        void enqueue(int x) {\n            if (isFull()) return;\n            if (last == max - 1 || last == -1) {\n                a[0] = x;\n                last = 0;\n                if (first == -1) first = 0;\n            } else {\n                a[++last] = x;\n            }\n        }\n\n        Integer front() {\n            if (isEmpty()) return null;\n            return a[first];\n        }\n\n        Integer dequeue() {\n            if (isEmpty()) return null;\n            int x = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return x;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int capacity = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue queue = new CircularQueue(capacity);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ENQ\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n                queue.enqueue(x);\n            } else if (line.equals(\"DEQ\")) {\n                Integer v = queue.dequeue();\n                out.append(v == null ? \"EMPT