        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        int[] a = new int[n];\n        int first = -1, last = -1;\n\n        for (int k = 0; k < m; k++) {\n            String op = sc.next();\n\n            if (op.equals(\"E\")) {\n                int x = sc.nextInt();\n                boolean isFull = (first == 0 && last == n - 1) || (first == last + 1);\n                if (!isFull) {\n                    if (first == -1) {\n                        first = last = 0;\n                    } else {\n                        last = (last + 1) % n;\n                    }\n                    a[last] = x;\n                }\n            } else if (op.equals(\"D\")) {\n                if (first != -1) {\n                    if (first == last) {\n                        first = last = -1;\n                    } else {\n                        first = (first + 1) % n;\n                    }\n                }\n            }\n        }\n\n        if (first == -1) {\n            System.out.println(\"EMPTY\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(\" \");\n                i = (i + 1) % n;\n            }\n            System.out.println(sb.toString());\n            System.out.println(\"first=\" + first);\n            System.out.println(\"last=\" + last);\n        }\n    }\n}\n"
