        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        int[] a;\n        int max;\n        int first;\n        int last;\n\n        CircularQueue(int max) {\n            this.max = max;\n            this.a = new int[max];\n            this.first = -1;\n            this.last = -1;\n        }\n\n        boolean isEmpty() {\n            return first == -1;\n        }\n\n        boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        void enqueue(int x) {\n            if (isFull()) return;\n\n            if (isEmpty()) {\n                first = last = 0;\n            } else if (last == max - 1) {\n                last = 0;\n            } else {\n                last++;\n            }\n            a[last] = x;\n        }\n\n        void dequeue() {\n            if (isEmpty()) return;\n\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n        }\n\n        String snapshot() {\n            if (isEmpty()) return \"EMPTY\";\n\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(' ');\n                i = (i + 1) % max;\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue queue = new CircularQueue(n);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ENQUEUE\")) {\n                String[] parts = line.split(\"\\\\s+\");\n