        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static boolean isEmpty(int first) {\n        return first == -1;\n    }\n\n    public static boolean isFull(int first, int last, int max) {\n        return (first == 0 && last == max - 1) || (first == last + 1);\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        int[] a = new int[n];\n        int first = -1, last = -1;\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ENQ\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n\n                if (!isFull(first, last, n)) {\n                    if (isEmpty(first)) {\n                        first = last = 0;\n                    } else {\n                        last = (last + 1) % n;\n                    }\n                    a[last] = x;\n                }\n            } else if (line.equals(\"DEQ\")) {\n                if (!isEmpty(first)) {\n                    if (first == last) {\n                        first = last = -1;\n                    } else {\n                        first = (first + 1) % n;\n                    }\n                }\n            }\n        }\n\n        if (isEmpty(first)) {\n            System.out.println(\"EMPTY\");\n            System.out.println(\"-1 -1\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(' ');\n                i = (i + 1) % n;\n            }\n            System.out.println(sb.toString());\n            System.out.println(first + \" \" + last);\n        }\n    }\n}\n"
      }
