        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        private int[] a;\n        private int max;\n        private int first;\n        private int last;\n\n        public CircularQueue(int max) {\n            this.max = max;\n            this.a = new int[max];\n            this.first = -1;\n            this.last = -1;\n        }\n\n        public boolean isEmpty() {\n            return first == -1;\n        }\n\n        public boolean isFull() {\n            return (first == 0 && last == max - 1) || first == last + 1;\n        }\n\n        public boolean enqueue(int x) {\n            if (isFull()) return false;\n            if (isEmpty()) {\n                first = last = 0;\n            } else if (last == max - 1) {\n                last = 0;\n            } else {\n                last++;\n            }\n            a[last] = x;\n            return true;\n        }\n\n        public Integer dequeue() {\n            if (isEmpty()) return null;\n            int val = a[first];\n            if (first == last) {\n                first = last = -1;\n            } else if (first == max - 1) {\n                first = 0;\n            } else {\n                first++;\n            }\n            return val;\n        }\n\n        public Integer peek() {\n            if (isEmpty()) return null;\n            return a[first];\n        }\n\n        public String remainingElements() {\n            if (isEmpty()) return \"EMPTY\";\n            StringBuilder sb = new StringBuilder();\n            int i = first;\n            while (true) {\n                sb.append(a[i]);\n                if (i == last) break;\n                sb.append(' ');\n                i = (i + 1) % max;\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue q = new CircularQueue(n);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ARRIVE\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n                if (!q.enqueue(x)) {\n                    out.append(\"FULL\\n\");\n                }\n            } else if (line.equals(\"SERVE\")) {\n                Integer val = q.dequeue();\n                if (val == null) out.append(\"EMPTY\\n\");\n                else out.append(val).append(\"\\n\");\n            } else if (line.equals(\"CHECK\")) {\n                Integer val = q.peek();\n                if (val == null) out.append(\"EMPTY\\n\");\n                else out.append(val).append(\"\\n\");\n            }\n        }\n\n        out.append(q.remainingElements());\n        System.out.print(out.toString());\n    }\n}\n"
