        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass CircularQueue {\n    private int[] a;\n    private int max;\n    private int first;\n    private int last;\n\n    public CircularQueue(int max) {\n        this.max = max;\n        a = new int[max];\n        first = -1;\n        last = -1;\n    }\n\n    public boolean isEmpty() {\n        return first == -1;\n    }\n\n    public boolean isFull() {\n        return (first == 0 && last == max - 1) || first == last + 1;\n    }\n\n    public boolean enqueue(int x) {\n        if (isFull()) {\n            return false;\n        }\n\n        if (isEmpty()) {\n            first = last = 0;\n        } else if (last == max - 1) {\n            last = 0;\n        } else {\n            last++;\n        }\n\n        a[last] = x;\n        return true;\n    }\n\n    public Integer dequeue() {\n        if (isEmpty()) {\n            return null;\n        }\n\n        int value = a[first];\n\n        if (first == last) {\n            first = last = -1;\n        } else if (first == max - 1) {\n            first = 0;\n        } else {\n            first++;\n        }\n\n        return value;\n    }\n\n    public Integer front() {\n        if (isEmpty()) {\n            return null;\n        }\n        return a[first];\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int q = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue queue = new CircularQueue(n);\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n\n            if (parts[0].equals(\"ENQ\")) {\n                int x = Integer.parseInt(parts[1]);\n                if (!queue.enqueue(x)) {\n                    out.append(\"FULL\\n\");\n                }\n            } else if (parts[0].equals(\"DEQ\")) {\n                Integer val = queue.dequeue();\n                if (val == null) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(val).append('\\n');\n                }\n            } else if (parts[0].equals(\"FRONT\")) {\n                Integer val = queue.front();\n                if (val == null) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(val).append('\\n');\n                }\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
