        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static class CircularQueue {\n        private int[] a;\n        private int first;\n        private int last;\n        private int size;\n\n        public CircularQueue(int capacity) {\n            a = new int[capacity];\n            first = -1;\n            last = -1;\n            size = 0;\n        }\n\n        public boolean isEmpty() {\n            return size == 0;\n        }\n\n        public boolean isFull() {\n            return size == a.length;\n        }\n\n        public boolean enqueue(int x) {\n            if (isFull()) return false;\n\n            if (isEmpty()) {\n                first = 0;\n                last = 0;\n            } else {\n                last = (last + 1) % a.length;\n            }\n            a[last] = x;\n            size++;\n            return true;\n        }\n\n        public Integer dequeue() {\n            if (isEmpty()) return null;\n\n            int val = a[first];\n            if (size == 1) {\n                first = -1;\n                last = -1;\n            } else {\n                first = (first + 1) % a.length;\n            }\n            size--;\n            return val;\n        }\n\n        public Integer peek() {\n            if (isEmpty()) return null;\n            return a[first];\n        }\n\n        public String contents() {\n            if (isEmpty()) return \"EMPTY\";\n\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < size; i++) {\n                if (i > 0) sb.append(' ');\n                sb.append(a[(first + i) % a.length]);\n            }\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        CircularQueue q = new CircularQueue(n);\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ENQ\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n                if (!q.enqueue(x)) {\n                    System.out.println(\"FULL\");\n                }\n            } else if (line.equals(\"DEQ\")) {\n                Integer val = q.dequeue();\n                if (val == null) System.out.println(\"EMPTY\");\n                else System.out.println(val);\n            } else if (line.equals(\"PEEK\")) {\n                Integer val = q.peek();\n                if (val == null) System.out.println(\"EMPTY\");\n                else System.out.println(val);\n            }\n        }\n\n        System.out.println(q.contents());\n    }\n}\n"
