    ],
    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int N = sc.nextInt();\n        int Q = sc.nextInt();\n\n        int[] queue = new int[N];\n        int f = -1;\n        int l = -1;\n        int size = 0;\n\n        for (int i = 0; i < Q; i++) {\n            String op = sc.next();\n\n            if (op.equals(\"ENQ\")) {\n                int x = sc.nextInt();\n                if (size == N) {\n                    continue;\n                }\n                if (size == 0) {\n                    f = 0;\n                    l = 0;\n                    queue[l] = x;\n                } else {\n                    l = (l + 1) % N;\n                    queue[l] = x;\n                }\n                size++;\n            } else if (op.equals(\"DEQ\")) {\n                if (size == 0) {\n                    continue;\n                }\n                if (size == 1) {\n                    f = -1;\n                    l = -1;\n                    size = 0;\n                } else {\n                    f = (f + 1) % N;\n                    size--;\n                }\n            }\n        }\n\n        if (size == 0) {\n            System.out.println(\"EMPTY\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < size; i++) {\n                if (i > 0) sb.append(' ');\n                sb.append(queue[(f + i) % N]);\n            }\n            System.out.println(sb.toString());\n            System.out.println(\"f=\" + f);\n            System.out.println(\"l=\" + l);\n        }\n    }\n}\n"
      }
