        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n        int[] keys = new int[n];\n        for (int i = 0; i < n; i++) {\n            keys[i] = sc.nextInt();\n        }\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        int failed = 0;\n\n        for (int key : keys) {\n            int h = key % M;\n            boolean placed = false;\n\n            for (int i = 0; i < M; i++) {\n                int idx = (h + i * i) % M;\n                if (table[idx] == -1) {\n                    table[idx] = key;\n                    placed = true;\n                    break;\n                }\n            }\n\n            if (!placed) {\n                failed++;\n            }\n        }\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n        System.out.println();\n        System.out.println(failed);\n    }\n}\n"
      }
