        "content": "import java.util.*;\n\nclass LibraryPass {\n    protected String holder;\n    protected int passId;\n\n    public LibraryPass(String holder, int passId) {\n        this.holder = holder;\n        this.passId = passId;\n    }\n\n    public String getCode() {\n        return holder + \"#\" + passId;\n    }\n\n    protected String getAccessDetail() {\n        return \"PASS\";\n    }\n\n    public String summarize() {\n        return getCode() + \":\" + getAccessDetail();\n    }\n}\n\nclass StudentPass extends LibraryPass {\n    private int borrowedBooks;\n\n    public StudentPass(String holder, int passId, int borrowedBooks) {\n        super(holder, passId);\n        this.borrowedBooks = borrowedBooks;\n    }\n\n    @Override\n    protected String getAccessDetail() {\n        if (borrowedBooks == 0) {\n            return \"STUDENT-CLEAR\";\n        }\n        if (borrowedBooks <= 3) {\n            return \"STUDENT-ACTIVE\";\n        }\n        return \"STUDENT-BUSY\";\n    }\n}\n\nclass LecturerPass extends LibraryPass {\n    private int reservedRooms;\n\n    public LecturerPass(String holder, int passId, int reservedRooms) {\n        super(holder, passId);\n        this.reservedRooms = reservedRooms;\n    }\n\n    @Override\n    protected String getAccessDetail() {\n        if (reservedRooms == 0) {\n            return \"LECTURER-FREE\";\n        }\n        if (reservedRooms <= 2) {\n            return \"LECTURER-SCHEDULED\";\n        }\n        return \"LECTURER-FULL\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        LibraryPass[] passes = new LibraryPass[n];\n\n        for (int i = 0; i < n; i++) {\n            String type = sc.next();\n            String holder = sc.next();\n            int passId = sc.nextInt();\n            int value = sc.nextInt();\n\n            if (type.equals(\"STUDENT\")) {\n                passes[i] = new S