    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int t = sc.nextInt();\n\n        boolean[] occupied = new boolean[M];\n        for (int i = 0; i < t; i++) {\n            int idx = sc.nextInt();\n            occupied[idx] = true;\n        }\n\n        int x = sc.nextInt();\n        int h = x % M;\n\n        StringBuilder path = new StringBuilder();\n        int found = -1;\n\n        for (int i = 0; i < M; i++) {\n            int pos = (h + i * i) % M;\n            if (i > 0) {\n                path.append(\" \");\n            }\n            path.append(pos);\n\n            if (!occupied[pos]) {\n                found = pos;\n                break;\n            }\n        }\n\n        System.out.println(path.toString());\n        System.out.println(found);\n    }\n}\n"
      }
