    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Entry {\n    protected String name;\n\n    public Entry(String name) {\n        this.name = name;\n    }\n\n    public String show() {\n        return name + \"=\" + toString();\n    }\n}\n\nclass PointEntry extends Entry {\n    private int x;\n    private int y;\n\n    public PointEntry(String name, int x, int y) {\n        super(name);\n        this.x = x;\n        this.y = y;\n    }\n\n    @Override\n    public String toString() {\n        return \"(\" + x + \",\" + y + \")\";\n    }\n}\n\nclass RangeEntry extends Entry {\n    private int start;\n    private int end;\n\n    public RangeEntry(String name, int start, int end) {\n        super(name);\n        this.start = start;\n        this.end = end;\n    }\n\n    @Override\n    public String toString() {\n        int small = Math.min(start, end);\n        int big = Math.max(start, end);\n        return \"[\" + small + \",\" + big + \"]\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Entry[] entries = new Entry[n];\n\n        for (int i = 0; i < n; i++) {\n            String type = sc.next();\n            String name = sc.next();\n            if (type.equals(\"POINT\")) {\n                int x = sc.nextInt();\n                int y = sc.nextInt();\n                entries[i] = new PointEntry(name, x, y);\n            } else if (type.equals(\"RANGE\")) {\n                int start = sc.nextInt();\n                int end = sc.nextInt();\n                entries[i] = new RangeEntry(name, start, end);\n            }\n        }\n\n        for (Entry entry : entries) {\n            System.out.println(entry.show());\n        }\n    }\n}\n"
