        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] keys = new int[n];\n        for (int i = 0; i < n; i++) {\n            keys[i] = sc.nextInt();\n        }\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        int[] placed = new int[n];\n        Arrays.fill(placed, -1);\n\n        for (int idx = 0; idx < n; idx++) {\n            int x = keys[idx];\n            int k = x % M;\n\n            if (table[k] == -1) {\n                table[k] = x;\n                placed[idx] = k;\n                continue;\n            }\n\n            boolean inserted = false;\n            for (int i = 1; i < M; i++) {\n                int pos = (k + i * i) % M;\n                if (table[pos] == -1) {\n                    table[pos] = x;\n                    placed[idx] = pos;\n                    inserted = true;\n                    break;\n                }\n            }\n\n            if (!inserted) {\n                placed[idx] = -1;\n            }\n        }\n\n        for (int i = 0; i < n; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(placed[i]);\n        }\n        System.out.println();\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n    }\n}\n"
