        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int N = sc.nextInt();\n\n        int[] keys = new int[N];\n        for (int i = 0; i < N; i++) {\n            keys[i] = sc.nextInt();\n        }\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n        int[] result = new int[N];\n\n        for (int i = 0; i < N; i++) {\n            int x = keys[i];\n            int h = x % M;\n            int insertedPos = -1;\n\n            for (int step = 0; step < M; step++) {\n                int pos = (h + step) % M;\n                if (table[pos] == -1) {\n                    table[pos] = x;\n                    insertedPos = pos;\n                    break;\n                }\n            }\n\n            result[i] = insertedPos;\n        }\n\n        for (int i = 0; i < N; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(result[i]);\n        }\n        System.out.println();\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n    }\n}\n"
