        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static int probeIndex(int key, int i, int m) {\n        return (key % m + i * i) % m;\n    }\n\n    static void insert(int[] table, int key) {\n        int m = table.length;\n        for (int i = 0; i < m; i++) {\n            int idx = probeIndex(key, i, m);\n            if (table[idx] == -1) {\n                table[idx] = key;\n                return;\n            }\n        }\n    }\n\n    static int search(int[] table, int key) {\n        int m = table.length;\n        for (int i = 0; i < m; i++) {\n            int idx = probeIndex(key, i, m);\n            if (table[idx] == -1) {\n                return -1;\n            }\n            if (table[idx] == key) {\n                return idx;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int N = sc.nextInt();\n        int Q = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < N; i++) {\n            int key = sc.nextInt();\n            insert(table, key);\n        }\n\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < Q; i++) {\n            int key = sc.nextInt();\n            if (i > 0) out.append(\" \");\n            out.append(search(table, key));\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
