        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            int h = key % M;\n            boolean inserted = false;\n\n            for (int probe = 0; probe < M; probe++) {\n                int pos = (h + probe) % M;\n                if (table[pos] == -1) {\n                    table[pos] = key;\n                    inserted = true;\n                    break;\n                }\n            }\n        }\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n    }\n}\n"
