        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static int findSlot(boolean[] table, int h) {\n        int m = table.length;\n\n        if (!table[h]) {\n            return h;\n        }\n\n        for (int i = 1; i < m; i++) {\n            int pos = (h + i) % m;\n            if (!table[pos]) {\n                return pos;\n            }\n        }\n\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n\n        boolean[] table = new boolean[m];\n        for (int i = 0; i < n; i++) {\n            int pos = sc.nextInt();\n            table[pos] = true;\n        }\n\n        int q = sc.nextInt();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            int h = sc.nextInt();\n            int ans = findSlot(table, h);\n            if (i > 0) sb.append(\" \");\n            sb.append(ans);\n        }\n\n        System.out.print(sb.toString());\n    }\n}\n"
