        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Participant {\n    protected String name;\n    protected int completedLessons;\n\n    public Participant(String name, int completedLessons) {\n        this.name = name;\n        this.completedLessons = completedLessons;\n    }\n\n    public String report() {\n        return name + \"@\" + completedLessons;\n    }\n}\n\nclass StudentParticipant extends Participant {\n    private int bonusLessons;\n\n    public StudentParticipant(String name, int completedLessons, int bonusLessons) {\n        super(name, completedLessons);\n        this.bonusLessons = bonusLessons;\n    }\n\n    @Override\n    public String report() {\n        int totalProgress = completedLessons + bonusLessons;\n        if (totalProgress >= 10) {\n            return name + \"@DONE@\" + totalProgress;\n        }\n        return name + \"@IN_PROGRESS@\" + (10 - totalProgress);\n    }\n}\n\nclass MentorParticipant extends Participant {\n    private int assistedGroups;\n\n    public MentorParticipant(String name, int completedLessons, int assistedGroups) {\n        super(name, completedLessons);\n        this.assistedGroups = assistedGroups;\n    }\n\n    @Override\n    public String report() {\n        if (completedLessons >= 8) {\n            return \"Mentor@\" + name + \"@READY@\" + assistedGroups;\n        }\n        return \"Mentor@\" + name + \"@TRAINING@\" + (8 - completedLessons);\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = Integer.parseInt(sc.nextLine().trim());\n        Participant[] participants = new Participant[n];\n\n        for (int i = 0; i < n; i++) {\n            String line = sc.nextLine().trim();\n            String[] parts = line.split(\"\\\\s+\");\n            String type = parts[0];\n\n            if (type.equals(\"S\")) {\n                String name = parts[1];\n                int completedLessons = Integer.parseInt(parts[2]);\n                int bonusLessons = Integer.parseInt(parts[3]);\n                participants[i] = new StudentParticipant(name, completedLessons, bonusLessons);\n            } else if (type.equals(\"M\")) {\n                String name = parts[1];\n                int completedLessons = Integer.parseInt(parts[2]);\n                int assistedGroups = Integer.parseInt(parts[3]);\n                participants[i] = new MentorParticipant(name, completedLessons, assistedGroups);\n            } else if (type.equals(\"P\")) {\n                String name = parts[1];\n                int completedLessons = Integer.parseInt(parts[2]);\n                participants[i] = new Participant(name, completedLessons);\n            }\n        }\n\n        for (Participant participant : participants) {\n            System.out.println(participant.report());\n        }\n    }\n}\n"
      }
