        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Dimension {\n    protected int x;\n    protected int y;\n\n    public Dimension(int x, int y) {\n        this.x = x;\n        this.y = y;\n    }\n\n    @Override\n    public String toString() {\n        return x + \"@\" + y;\n    }\n}\n\nclass ReversedDimension extends Dimension {\n    public ReversedDimension(int x, int y) {\n        super(x, y);\n    }\n\n    @Override\n    public String toString() {\n        return y + \"@\" + x;\n    }\n}\n\nclass BoxDimension extends Dimension {\n    private int z;\n\n    public BoxDimension(int x, int y, int z) {\n        super(x, y);\n        this.z = z;\n    }\n\n    @Override\n    public String toString() {\n        return super.toString() + \"@\" + z;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Dimension[] items = new Dimension[n];\n\n        for (int i = 0; i < n; i++) {\n            String type = sc.next();\n            if (type.equals(\"NORMAL\")) {\n                int x = sc.nextInt();\n                int y = sc.nextInt();\n                items[i] = new Dimension(x, y);\n            } else if (type.equals(\"REVERSED\")) {\n                int x = sc.nextInt();\n                int y = sc.nextInt();\n                items[i] = new ReversedDimension(x, y);\n            } else if (type.equals(\"BOX\")) {\n                int x = sc.nextInt();\n                int y = sc.nextInt();\n                int z = sc.nextInt();\n                items[i] = new BoxDimension(x, y, z);\n            }\n        }\n\n        for (Dimension item : items) {\n            System.out.println(item.toString());\n        }\n    }\n}\n"
