        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Rectangle {\n    protected int length;\n    protected int width;\n\n    public Rectangle(int length, int width) {\n        this.length = length;\n        this.width = width;\n    }\n\n    public void resize(int value) {\n        length += value;\n        width += value;\n    }\n\n    @Override\n    public String toString() {\n        return length + \"@\" + width;\n    }\n}\n\nclass Box extends Rectangle {\n    private int height;\n\n    public Box(int length, int width, int height) {\n        super(length, width);\n        this.height = height;\n    }\n\n    @Override\n    public void resize(int value) {\n        super.resize(value);\n        height += value;\n    }\n\n    @Override\n    public String toString() {\n        return super.toString() + \"@\" + height;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Rectangle[] items = new Rectangle[n];\n\n        for (int i = 0; i < n; i++) {\n            String type = sc.next();\n            if (type.equals(\"R\")) {\n                int length = sc.nextInt();\n                int width = sc.nextInt();\n                items[i] = new Rectangle(length, width);\n            } else {\n                int length = sc.nextInt();\n                int width = sc.nextInt();\n                int height = sc.nextInt();\n                items[i] = new Box(length, width, height);\n            }\n        }\n\n        int k = sc.nextInt();\n\n        for (Rectangle item : items) {\n            item.resize(k);\n        }\n\n        for (Rectangle item : items) {\n            System.out.println(item);\n        }\n    }\n}\n"
