        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Sheet {\n    protected int width;\n    protected int height;\n\n    public Sheet(int width, int height) {\n        this.width = width;\n        this.height = height;\n    }\n\n    @Override\n    public String toString() {\n        return width + \"@\" + height;\n    }\n}\n\nclass StackedSheet extends Sheet {\n    private int layers;\n\n    public StackedSheet(int width, int height, int layers) {\n        super(width, height);\n        this.layers = layers;\n    }\n\n    @Override\n    public String toString() {\n        return super.toString() + \"@\" + layers;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Sheet[] items = new Sheet[n];\n\n        for (int i = 0; i < n; i++) {\n            int type = sc.nextInt();\n            int width = sc.nextInt();\n            int height = sc.nextInt();\n\n            if (type == 1) {\n                items[i] = new Sheet(width, height);\n            } else {\n                int layers = sc.nextInt();\n                items[i] = new StackedSheet(width, height, layers);\n            }\n        }\n\n        for (Sheet item : items) {\n            System.out.println(item.toString());\n        }\n    }\n}\n"
