        "content": "import java.util.*;\n\nclass Contact {\n    protected String name;\n    protected String phone;\n    protected int missedCalls;\n\n    public Contact(String name, String phone) {\n        this.name = name;\n        this.phone = phone;\n        this.missedCalls = 0;\n    }\n\n    public void addMissedCalls(int count) {\n        if (count > 0) {\n            missedCalls += count;\n        }\n    }\n\n    public String getSummary() {\n        if (missedCalls == 0) {\n            return name + \"@\" + phone + \"@NONE\";\n        }\n        return name + \"@\" + phone + \"@MISSED-\" + missedCalls;\n    }\n}\n\nclass EmergencyContact extends Contact {\n    private String relation;\n\n    public EmergencyContact(String name, String phone, String relation) {\n        super(name, phone);\n        this.relation = relation;\n    }\n\n    @Override\n    public String getSummary() {\n        if (missedCalls == 0) {\n            return name + \"@\" + phone + \"@\" + relation + \"@NORMAL\";\n        } else if (missedCalls <= 2) {\n            return name + \"@\" + phone + \"@\" + relation + \"@MISSED-\" + missedCalls;\n        }\n        return name + \"@\" + phone + \"@\" + relation + \"@URGENT-\" + missedCalls;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Contact[] contacts = new Contact[n];\n        int totalMissedCalls = 0;\n\n        for (int i = 0; i < n; i++) {\n            int type = sc.nextInt();\n            if (type == 1) {\n                String name = sc.next();\n                String phone = sc.next();\n                int missed = sc.nextInt();\n                contacts[i] = new Contact(name, phone);\n                contacts[i].addMissedCalls(missed);\n                totalMissedCalls += Math.max(0, missed);\n            } else {\n                String name = sc.next();\n                String phone = sc.next();\n           