        "content": "import java.util.*;\n\nclass Board {\n    protected int rows;\n    protected int columns;\n\n    public Board(int rows, int columns) {\n        this.rows = rows;\n        this.columns = columns;\n    }\n\n    public void expand(int addRows, int addColumns) {\n        rows += addRows;\n        columns += addColumns;\n    }\n\n    @Override\n    public String toString() {\n        return rows + \"@\" + columns;\n    }\n}\n\nclass LayeredBoard extends Board {\n    private int layers;\n\n    public LayeredBoard(int rows, int columns, int layers) {\n        super(rows, columns);\n        this.layers = layers;\n    }\n\n    public void addLayers(int extra) {\n        layers += extra;\n    }\n\n    @Override\n    public String toString() {\n        return super.toString() + \"@\" + layers;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        Board[] boards = new Board[n];\n\n        for (int i = 0; i < n; i++) {\n            int type = sc.nextInt();\n            if (type == 1) {\n                int rows = sc.nextInt();\n                int columns = sc.nextInt();\n                int addRows = sc.nextInt();\n                int addColumns = sc.nextInt();\n\n                Board b = new Board(rows, columns);\n                b.expand(addRows, addColumns);\n                boards[i] = b;\n            } else {\n                int rows = sc.nextInt();\n                int columns = sc.nextInt();\n                int layers = sc.nextInt();\n                int addRows = sc.nextInt();\n                int addColumns = sc.nextInt();\n                int extraLayers = sc.nextInt();\n\n                LayeredBoard lb = new LayeredBoard(rows, columns, layers);\n                lb.expand(addRows, addColumns);\n                lb.addLayers(extraLayers);\n                boards[i] = lb;\n            }\n        }\n\n        for (Board b : boards) {\n            System.out.println(b.toString());\n        }\n    }\n}\n"
