        "content": "import java.util.*;\n\nclass Room {\n    private int width;\n    private int length;\n\n    public Room(int width, int length) {\n        this.width = width;\n        this.length = length;\n    }\n\n    protected int getWidth() {\n        return width;\n    }\n\n    protected int getLength() {\n        return length;\n    }\n\n    protected void setWidth(int width) {\n        this.width = width;\n    }\n\n    protected void setLength(int length) {\n        this.length = length;\n    }\n\n    public void expand(int factor) {\n        if (factor > 0) {\n            width *= factor;\n            length *= factor;\n        }\n    }\n\n    public int getArea() {\n        return width * length;\n    }\n\n    protected String getShape() {\n        return width + \"@\" + length;\n    }\n\n    @Override\n    public String toString() {\n        return getShape() + \"@\" + getArea();\n    }\n}\n\nclass WarehouseRoom extends Room {\n    private int floors;\n\n    public WarehouseRoom(int width, int length, int floors) {\n        super(width, length);\n        this.floors = floors;\n    }\n\n    @Override\n    public void expand(int factor) {\n        if (factor > 0) {\n            super.expand(factor);\n            floors *= factor;\n        }\n    }\n\n    @Override\n    public int getArea() {\n        return getWidth() * getLength() * floors;\n    }\n\n    @Override\n    protected String getShape() {\n        return getWidth() + \"@\" + getLength() + \"@\" + floors;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int width = sc.nextInt();\n        int length = sc.nextInt();\n\n        int warehouseWidth = sc.nextInt();\n        int warehouseLength = sc.nextInt();\n        int floors = sc.nextInt();\n\n        int factorForRoom = sc.nextInt();\n        int factorForWarehouse = sc.nextInt();\n\n        Room[] rooms = new Room[2];\n        rooms[0] = new Room(width, length);\n        rooms[1] = new WarehouseRoom(warehouseWidth, warehouseLength, floors);\n\n        int[] factors = {factorForRoom, factorForWarehouse};\n\n        for (int i = 0; i < rooms.length; i++) {\n            rooms[i].expand(factors[i]);\n            System.out.println(rooms[i]);\n        }\n    }\n}\n"
