        "content": "import java.util.*;\n\nclass Ticket {\n    protected String code;\n    protected int progress;\n\n    public Ticket(String code, int progress) {\n        this.code = code;\n        if (progress < 0) {\n            this.progress = 0;\n        } else if (progress > 100) {\n            this.progress = 100;\n        } else {\n            this.progress = progress;\n        }\n    }\n\n    public void updateProgress(int units) {\n    }\n\n    public String getCode() {\n        return code;\n    }\n\n    public int getProgress() {\n        return progress;\n    }\n}\n\nclass FastTicket extends Ticket {\n    public FastTicket(String code, int progress) {\n        super(code, progress);\n    }\n\n    @Override\n    public void updateProgress(int units) {\n        if (units > 0) {\n            progress += units;\n            if (progress > 100) {\n                progress = 100;\n            }\n        }\n    }\n}\n\nclass ApprovalTicket extends Ticket {\n    public ApprovalTicket(String code, int progress) {\n        super(code, progress);\n    }\n\n    @Override\n    public void updateProgress(int units) {\n        if (units <= 0) {\n            return;\n        }\n\n        if (progress < 80) {\n            progress += units;\n            if (progress > 80) {\n                progress = 80;\n            }\n        } else if (progress == 80) {\n            if (units >= 20) {\n                progress = 100;\n            }\n        }\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        Ticket[] tickets = new Ticket[2];\n\n        for (int i = 0; i < 2; i++) {\n            String type = sc.next();\n            String code = sc.next();\n            int initialProgress = sc.nextInt();\n            int firstUpdate = sc.nextInt();\n            int secondUpdate = sc.nextInt();\n\n            if (type.equals(\"FAST\")) {\n                tickets[i] = new FastTicket(code, initialProgress);\n            } else {\n                tickets[i] = new ApprovalTicket(code, initialProgress);\n            }\n\n            tickets[i].updateProgress(firstUpdate);\n            tickets[i].updateProgress(secondUpdate);\n        }\n\n        for (Ticket ticket : tickets) {\n            System.out.println(ticket.getCode() + \": \" + ticket.getProgress());\n        }\n    }\n}\n"
