        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass TextFormatter {\n    protected String text;\n\n    public TextFormatter(String text) {\n        this.text = text;\n    }\n\n    public String normalize() {\n        return text.trim().replaceAll(\"\\\\s+\", \" \");\n    }\n\n    public String format() {\n        return normalize();\n    }\n}\n\nclass UpperCaseFormatter extends TextFormatter {\n    public UpperCaseFormatter(String text) {\n        super(text);\n    }\n\n    @Override\n    public String format() {\n        return normalize().toUpperCase();\n    }\n}\n\nclass ReverseWordsFormatter extends TextFormatter {\n    public ReverseWordsFormatter(String text) {\n        super(text);\n    }\n\n    @Override\n    public String format() {\n        String normalized = normalize();\n        if (normalized.isEmpty()) {\n            return \"\";\n        }\n\n        String[] words = normalized.split(\" \");\n        StringBuilder sb = new StringBuilder();\n        for (int i = words.length - 1; i >= 0; i--) {\n            sb.append(words[i]);\n            if (i > 0) {\n                sb.append(\" \");\n            }\n        }\n        return sb.toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String input = sc.nextLine();\n\n        TextFormatter[] formatters = {\n            new UpperCaseFormatter(input),\n            new ReverseWordsFormatter(input)\n        };\n\n        for (TextFormatter formatter : formatters) {\n            System.out.println(formatter.format());\n        }\n    }\n}\n"
