        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        Integer[] table = new Integer[M];\n\n        for (int t = 0; t < n; t++) {\n            int key = sc.nextInt();\n            int h = sc.nextInt();\n\n            for (int i = 0; i < M; i++) {\n                int pos = (h + i) % M;\n                if (table[pos] == null) {\n                    table[pos] = key;\n                    break;\n                }\n            }\n        }\n\n        int q = sc.nextInt();\n        StringBuilder out = new StringBuilder();\n\n        for (int t = 0; t < q; t++) {\n            int key = sc.nextInt();\n            int h = sc.nextInt();\n            int answer = -1;\n\n            for (int i = 0; i < M; i++) {\n                int pos = (h + i) % M;\n                if (table[pos] == null) {\n                    answer = -1;\n                    break;\n                }\n                if (table[pos] == key) {\n                    answer = pos;\n                    break;\n                }\n            }\n\n            out.append(answer);\n            if (t < q - 1) {\n                out.append('\\n');\n            }\n        }\n\n        System.out.print(out.toString());\n        sc.close();\n    }\n}\n"
