        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[M];\n        boolean[] used = new boolean[M];\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            int h = key % M;\n            for (int j = 0; j < M; j++) {\n                int idx = (h + j * j) % M;\n                if (!used[idx]) {\n                    used[idx] = true;\n                    table[idx] = key;\n                    break;\n                }\n            }\n        }\n\n        int q = sc.nextInt();\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < q; i++) {\n            int key = sc.nextInt();\n            int h = key % M;\n            int answer = -1;\n\n            for (int j = 0; j < M; j++) {\n                int idx = (h + j * j) % M;\n                if (!used[idx]) {\n                    break;\n                }\n                if (table[idx] == key) {\n                    answer = idx;\n                    break;\n                }\n            }\n\n            out.append(answer);\n            if (i < q - 1) {\n                out.append('\\n');\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
