        "content": "import java.util.*;\n\npublic class Main {\n    static int search(int[] table, boolean[] used, int m, int key) {\n        int start = key % m;\n        for (int i = 0; i < m; i++) {\n            int idx = (start + i) % m;\n            if (!used[idx]) {\n                return -1;\n            }\n            if (table[idx] == key) {\n                return idx;\n            }\n        }\n        return -1;\n    }\n\n    static void insert(int[] table, boolean[] used, int m, int key) {\n        int start = key % m;\n        for (int i = 0; i < m; i++) {\n            int idx = (start + i) % m;\n            if (!used[idx]) {\n                table[idx] = key;\n                used[idx] = true;\n                return;\n            }\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[m];\n        boolean[] used = new boolean[m];\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            insert(table, used, m, key);\n        }\n\n        int q = sc.nextInt();\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < q; i++) {\n            int key = sc.nextInt();\n            sb.append(search(table, used, m, key)).append(\"\\n\");\n        }\n\n        System.out.print(sb.toString());\n        sc.close();\n    }\n}\n"
