        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int[] table = new int[M];\n\n        for (int i = 0; i < M; i++) {\n            table[i] = sc.nextInt();\n        }\n\n        int h = sc.nextInt();\n        int target = sc.nextInt();\n\n        for (int i = 0; i < M; i++) {\n            int pos = (h + i * i) % M;\n            if (table[pos] == -1) {\n                System.out.println(-1);\n                return;\n            }\n            if (table[pos] == target) {\n                System.out.println(pos);\n                return;\n            }\n        }\n\n        System.out.println(-1);\n    }\n}\n"
