        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    private static int hash(int x, int M) {\n        return x % M;\n    }\n\n    private static void insert(int[] table, int key) {\n        int M = table.length;\n        int h = hash(key, M);\n\n        if (table[h] == -1) {\n            table[h] = key;\n            return;\n        }\n\n        for (int i = 1; i < M; i++) {\n            int pos = (h + i) % M;\n            if (table[pos] == -1) {\n                table[pos] = key;\n                return;\n            }\n        }\n    }\n\n    private static int search(int[] table, int key) {\n        int M = table.length;\n        int h = hash(key, M);\n\n        if (table[h] == key) {\n            return h;\n        }\n        if (table[h] == -1) {\n            return -1;\n        }\n\n        for (int i = 1; i < M; i++) {\n            int pos = (h + i) % M;\n            if (table[pos] == key) {\n                return pos;\n            }\n            if (table[pos] == -1) {\n                return -1;\n            }\n        }\n\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int M = sc.nextInt();\n        int N = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < N; i++) {\n            int key = sc.nextInt();\n            insert(table, key);\n        }\n\n        int Q = sc.nextInt();\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < Q; i++) {\n            int key = sc.nextInt();\n            if (i > 0) out.append(\" \");\n            out.append(search(table, key));\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
