        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static int hash(int x, int m) {\n        return x % m;\n    }\n\n    static void insert(int[] table, int key) {\n        int m = table.length;\n        int h = hash(key, m);\n\n        for (int i = 0; i < m; i++) {\n            int idx = (h + i * i) % m;\n            if (table[idx] == -1) {\n                table[idx] = key;\n                return;\n            }\n        }\n    }\n\n    static int search(int[] table, int key) {\n        int m = table.length;\n        int h = hash(key, m);\n\n        for (int i = 0; i < m; i++) {\n            int idx = (h + i * i) % m;\n            if (table[idx] == -1) {\n                return -1;\n            }\n            if (table[idx] == key) {\n                return idx;\n            }\n        }\n\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[m];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            insert(table, key);\n        }\n\n        int q = sc.nextInt();\n        StringBuilder out = new StringBuilder();\n        for (int i = 0; i < q; i++) {\n            int key = sc.nextInt();\n            out.append(search(table, key));\n            if (i < q - 1) out.append(\"\\n\");\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
