        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static int hash(int x, int m) {\n        return x % m;\n    }\n\n    static void insert(int[] table, boolean[] used, int key, int m) {\n        int h = hash(key, m);\n        for (int i = 0; i < m; i++) {\n            int pos = (h + i * i) % m;\n            if (!used[pos]) {\n                table[pos] = key;\n                used[pos] = true;\n                return;\n            }\n        }\n    }\n\n    static int search(int[] table, boolean[] used, int key, int m) {\n        int h = hash(key, m);\n        for (int i = 0; i < m; i++) {\n            int pos = (h + i * i) % m;\n            if (!used[pos]) {\n                return -1;\n            }\n            if (table[pos] == key) {\n                return pos;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[m];\n        boolean[] used = new boolean[m];\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            insert(table, used, key, m);\n        }\n\n        int q = sc.nextInt();\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < q; i++) {\n            int key = sc.nextInt();\n            if (i > 0) out.append(\" \");\n            out.append(search(table, used, key, m));\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
