        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int[] table = new int[M];\n\n        for (int i = 0; i < M; i++) {\n            table[i] = sc.nextInt();\n        }\n\n        int N = sc.nextInt();\n        int[] home = new int[N];\n        for (int i = 0; i < N; i++) {\n            home[i] = sc.nextInt();\n        }\n\n        StringBuilder out = new StringBuilder();\n\n        for (int q = 0; q < N; q++) {\n            int h = home[q];\n            int placed = -1;\n\n            for (int i = 0; i < M; i++) {\n                int pos = (h + i) % M;\n                if (table[pos] == 0) {\n                    table[pos] = 1;\n                    placed = pos;\n                    break;\n                }\n            }\n\n            out.append(placed);\n            if (q < N - 1) {\n                out.append(\"\\n\");\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
      }
