        "content": "import java.util.*;\n\npublic class Main {\n    static int search(int[] table, int key) {\n        int m = table.length;\n        int h = key % m;\n\n        for (int i = 0; i < m; i++) {\n            int idx = (h + i) % m;\n            if (table[idx] == key) {\n                return idx;\n            }\n            if (table[idx] == -1) {\n                return -1;\n            }\n        }\n\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int[] table = new int[m];\n\n        for (int i = 0; i < m; i++) {\n            table[i] = sc.nextInt();\n        }\n\n        int q = sc.nextInt();\n        for (int i = 0; i < q; i++) {\n            int key = sc.nextInt();\n            System.out.println(search(table, key));\n        }\n    }\n}\n"
