        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int item = 0; item < n; item++) {\n            int value = sc.nextInt();\n            int homeIndex = sc.nextInt();\n\n            boolean placed = false;\n            for (int i = 0; i < M; i++) {\n                int pos;\n                if (i == 0) {\n                    pos = homeIndex;\n                } else {\n                    pos = (homeIndex + i * i) % M;\n                }\n\n                if (table[pos] == -1) {\n                    table[pos] = value;\n                    placed = true;\n                    break;\n                }\n            }\n\n            if (!placed) {\n                // Ignore this value if no empty slot can be found.\n            }\n        }\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n    }\n}\n"
