        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        int[] queue = new int[n];\n\n        // Implement a circular array-based queue.\n        // Print front index and last index on the first line.\n        // Print queue elements from front to rear on the second line,\n        // or EMPTY if the queue has no elements.\n    }\n}\n",
        "is_readonly": false
      }
    ],
    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        int[] queue = new int[n];\n        int f = -1;\n        int l = -1;\n        int size = 0;\n\n        for (int i = 0; i < m; i++) {\n            String cmd = sc.next();\n\n            if (cmd.equals(\"ENQ\")) {\n                int x = sc.nextInt();\n                if (n == 0 || size == n) {\n                    continue;\n                }\n\n                if (size == 0) {\n                    f = 0;\n                    l = 0;\n                    queue[l] = x;\n                } else {\n                    l = (l + 1) % n;\n                    queue[l] = x;\n                }\n                size++;\n            } else if (cmd.equals(\"DEQ\")) {\n                if (size == 0) {\n                    continue;\n                }\n\n                if (size == 1) {\n                    f = -1;\n                    l = -1;\n                    size = 0;\n                } else {\n                    f = (f + 1) % n;\n                    size--;\n                }\n            }\n        }\n\n        if (size == 0) {\n            System.out.println(\"-1 -1\");\n            System.out.println(\"EMPTY\");\n        } else {\n            System.out.println(f + \" \" + l);\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < size; i++) {\n                if (i > 0) sb.append(' ');\n                sb.append(queue[(f + i) % n]);\n            }\n            System.out.println(sb.toString());\n        }\n    }\n}\n"
      }
