    "solution_code": [
      {
        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n\n        int[] queue = new int[Math.max(n, 0)];\n        int front = -1;\n        int rear = -1;\n        int size = 0;\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String cmd = sc.next();\n\n            if (cmd.equals(\"ENQ\")) {\n                int x = sc.nextInt();\n                if (n == 0 || size == n) {\n                    continue;\n                }\n                if (size == 0) {\n                    front = 0;\n                    rear = 0;\n                    queue[rear] = x;\n                } else {\n                    rear = (rear + 1) % n;\n                    queue[rear] = x;\n                }\n                size++;\n            } else if (cmd.equals(\"DEQ\")) {\n                if (size == 0) {\n                    continue;\n                }\n                if (size == 1) {\n                    front = -1;\n                    rear = -1;\n                    size = 0;\n                } else {\n                    front = (front + 1) % n;\n                    size--;\n                }\n            } else if (cmd.equals(\"REPORT\")) {\n                if (size == 0) {\n                    out.append(\"-1 -1 0 EMPTY\");\n                } else {\n                    out.append(front).append(' ').append(rear).append(' ').append(size);\n                    for (int k = 0; k < size; k++) {\n                        out.append(' ').append(queue[(front + k) % n]);\n                    }\n                }\n                if (i < m - 1) {\n                    out.append('\\n');\n                }\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
      }
