        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        int[] queue = new int[n];\n        int front = -1;\n        int rear = -1;\n        int size = 0;\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            if (line.startsWith(\"ADD\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n\n                if (size == n) {\n                    continue;\n                }\n\n                if (size == 0) {\n                    front = 0;\n                    rear = 0;\n                    queue[rear] = x;\n                } else {\n                    rear = (rear + 1) % n;\n                    queue[rear] = x;\n                }\n                size++;\n            } else if (line.equals(\"PRINT\")) {\n                if (size == 0) {\n                    continue;\n                }\n\n                if (size == 1) {\n                    front = -1;\n                    rear = -1;\n                    size = 0;\n                } else {\n                    front = (front + 1) % n;\n                    size--;\n                }\n            } else if (line.equals(\"NEXT\")) {\n                if (size == 0) {\n                    System.out.println(\"EMPTY\");\n                } else {\n                    System.out.println(queue[front]);\n                }\n            }\n        }\n    }\n}\n"
      }
