        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int m = sc.nextInt();\n        sc.nextLine();\n\n        int[] queue = new int[n];\n        int front = 0;\n        int rear = -1;\n        int size = 0;\n        StringBuilder out = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n\n            if (line.startsWith(\"ENQUEUE\")) {\n                String[] parts = line.split(\"\\\\s+\");\n                int x = Integer.parseInt(parts[1]);\n                if (size < n) {\n                    rear = (rear + 1) % n;\n                    queue[rear] = x;\n                    size++;\n                }\n            } else if (line.equals(\"DEQUEUE\")) {\n                if (size > 0) {\n                    front = (front + 1) % n;\n                    size--;\n                    if (size == 0) {\n                        front = 0;\n                        rear = -1;\n                    }\n                }\n            } else if (line.equals(\"FRONT\")) {\n                if (size == 0) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    out.append(queue[front]).append('\\n');\n                }\n            } else if (line.equals(\"REPORT\")) {\n                if (size == 0) {\n                    out.append(\"EMPTY\\n\");\n                } else {\n                    for (int k = 0; k < size; k++) {\n                        if (k > 0) out.append(' ');\n                        out.append(queue[(front + k) % n]);\n                    }\n                    out.append('\\n');\n                }\n            }\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
