        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass TextStyle {\n    protected String text;\n\n    public TextStyle(String text) {\n        this.text = text;\n    }\n\n    public void setText(String text) {\n        this.text = text;\n    }\n\n    public String render() {\n        return text;\n    }\n}\n\nclass UpperStyle extends TextStyle {\n    public UpperStyle(String text) {\n        super(text);\n    }\n\n    @Override\n    public String render() {\n        return text.toUpperCase();\n    }\n}\n\nclass RepeatStyle extends TextStyle {\n    private int repeatCount;\n\n    public RepeatStyle(String text, int repeatCount) {\n        super(text);\n        this.repeatCount = repeatCount;\n    }\n\n    @Override\n    public String render() {\n        if (repeatCount <= 0) {\n            return \"\";\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < repeatCount; i++) {\n            if (i > 0) {\n                sb.append(\"|\");\n            }\n            sb.append(text);\n        }\n        return sb.toString();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String firstText = sc.nextLine();\n        int repeatCount = Integer.parseInt(sc.nextLine());\n        String secondText = sc.nextLine();\n\n        TextStyle[] styles = new TextStyle[3];\n        styles[0] = new TextStyle(firstText);\n        styles[1] = new UpperStyle(firstText);\n        styles[2] = new RepeatStyle(firstText, repeatCount);\n\n        for (TextStyle style : styles) {\n            System.out.println(style.render());\n        }\n\n        for (TextStyle style : styles) {\n            style.setText(secondText);\n        }\n\n        for (TextStyle style : styles) {\n            System.out.println(style.render());\n        }\n    }\n}\n"
