        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Shipment {\n    protected String name;\n    protected int distance;\n\n    public Shipment(String name, int distance) {\n        this.name = name;\n        setDistance(distance);\n    }\n\n    public void setDistance(int distance) {\n        this.distance = Math.max(0, distance);\n    }\n\n    public int calculateCost() {\n        return 0;\n    }\n\n    public String getReport() {\n        return name + \":\" + calculateCost();\n    }\n}\n\nclass StandardShipment extends Shipment {\n    public StandardShipment(String name, int distance) {\n        super(name, distance);\n    }\n\n    @Override\n    public int calculateCost() {\n        if (distance == 0) {\n            return 0;\n        }\n        if (distance <= 5) {\n            return 10;\n        }\n        return 10 + (distance - 5) * 2;\n    }\n}\n\nclass ExpressShipment extends Shipment {\n    public ExpressShipment(String name, int distance) {\n        super(name, distance);\n    }\n\n    @Override\n    public int calculateCost() {\n        if (distance == 0) {\n            return 0;\n        }\n        if (distance <= 3) {\n            return 20;\n        }\n        return 20 + (distance - 3) * 4;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String name1 = sc.next();\n        int distance1 = sc.nextInt();\n        String name2 = sc.next();\n        int distance2 = sc.nextInt();\n        int newDistance1 = sc.nextInt();\n        int newDistance2 = sc.nextInt();\n\n        Shipment s1 = new StandardShipment(name1, distance1);\n        Shipment s2 = new ExpressShipment(name2, distance2);\n\n        System.out.println(s1.getReport());\n        System.out.println(s2.getReport());\n\n        s1.setDistance(newDistance1);\n        s2.setDistance(newDistance2);\n\n        System.out.println(s1.getReport());\n        System.out.println(s2.getReport());\n    }\n}\n"
