        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass TextAction {\n    protected String text;\n\n    public TextAction(String text) {\n        this.text = text;\n    }\n\n    public String process() {\n        return text;\n    }\n\n    public String getReport() {\n        return process() + \" (\" + text.length() + \")\";\n    }\n}\n\nclass ReverseAction extends TextAction {\n    public ReverseAction(String text) {\n        super(text);\n    }\n\n    @Override\n    public String process() {\n        return \"\";\n    }\n}\n\nclass UpperAction extends TextAction {\n    public UpperAction(String text) {\n        super(text);\n    }\n\n    @Override\n    public String process() {\n        return \"\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String first = sc.nextLine();\n        String second = sc.nextLine();\n\n        TextAction action1 = new ReverseAction(first);\n        TextAction action2 = new UpperAction(second);\n\n        System.out.println(action1.getReport());\n        System.out.println(action2.getReport());\n    }\n}\n",
