        "content": "import java.util.*;\n\nclass Booking {\n    protected int distance;\n    protected int passengers;\n\n    public Booking(int distance, int passengers) {\n        this.distance = distance;\n        this.passengers = passengers;\n    }\n\n    public int calculateCost() {\n        return 0;\n    }\n\n    public boolean isValid() {\n        return distance > 0 && passengers > 0;\n    }\n\n    public String getReport() {\n        if (!isValid()) {\n            return \"INVALID\";\n        }\n        return String.valueOf(calculateCost());\n    }\n}\n\nclass BusBooking extends Booking {\n    public BusBooking(int distance, int passengers) {\n        super(distance, passengers);\n    }\n\n    @Override\n    public int calculateCost() {\n        return 0;\n    }\n}\n\nclass TaxiBooking extends Booking {\n    public TaxiBooking(int distance, int passengers) {\n        super(distance, passengers);\n    }\n\n    @Override\n    public int calculateCost() {\n        return 0;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int busDistance = sc.nextInt();\n        int busPassengers = sc.nextInt();\n        int taxiDistance = sc.nextInt();\n        int taxiPassengers = sc.nextInt();\n\n        Booking booking1 = new BusBooking(busDistance, busPassengers);\n        Booking booking2 = new TaxiBooking(taxiDistance, taxiPassengers);\n\n        System.out.println(booking1.getReport());\n        System.out.println(booking2.getReport());\n    }\n}\n",
