        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass NumberCounter {\n    protected int start;\n    protected int end;\n\n    public NumberCounter(int start, int end) {\n        this.start = start;\n        this.end = end;\n    }\n\n    public boolean isMatch(int n) {\n        return false;\n    }\n\n    public int countMatches() {\n        if (start > end) {\n            return 0;\n        }\n\n        int count = 0;\n        for (int i = start; i <= end; i++) {\n            if (isMatch(i)) {\n                count++;\n            }\n        }\n        return count;\n    }\n}\n\nclass EvenCounter extends NumberCounter {\n    public EvenCounter(int start, int end) {\n        super(start, end);\n    }\n\n    @Override\n    public boolean isMatch(int n) {\n        return n % 2 == 0;\n    }\n}\n\nclass PrimeCounter extends NumberCounter {\n    public PrimeCounter(int start, int end) {\n        super(start, end);\n    }\n\n    @Override\n    public boolean isMatch(int n) {\n        if (n <= 1) {\n            return false;\n        }\n        for (int i = 2; i * i <= n; i++) {\n            if (n % i == 0) {\n                return false;\n            }\n        }\n        return true;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int start = sc.nextInt();\n        int end = sc.nextInt();\n\n        NumberCounter evenCounter = new EvenCounter(start, end);\n        NumberCounter primeCounter = new PrimeCounter(start, end);\n\n        System.out.println(evenCounter.countMatches());\n        System.out.println(primeCounter.countMatches());\n    }\n}\n"
