        "content": "import java.util.*;\n\npublic class Main {\n    static int hash(int x, int m) {\n        int r = x % m;\n        return r < 0 ? r + m : r;\n    }\n\n    static int insert(int[] table, int key) {\n        int m = table.length;\n        int h = hash(key, m);\n\n        for (int i = 0; i < m; i++) {\n            int idx = (h + i) % m;\n            if (table[idx] == key) {\n                return idx;\n            }\n            if (table[idx] == -1) {\n                table[idx] = key;\n                return idx;\n            }\n        }\n        return -1;\n    }\n\n    static int search(int[] table, int key) {\n        int m = table.length;\n        int h = hash(key, m);\n\n        for (int i = 0; i < m; i++) {\n            int idx = (h + i) % m;\n            if (table[idx] == key) {\n                return idx;\n            }\n            if (table[idx] == -1) {\n                return -1;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int M = sc.nextInt();\n        int N = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < N; i++) {\n            int key = sc.nextInt();\n            insert(table, key);\n        }\n\n        int Q = sc.nextInt();\n        int[] ans = new int[Q];\n        for (int i = 0; i < Q; i++) {\n            int key = sc.nextInt();\n            ans[i] = search(table, key);\n        }\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n        System.out.println();\n\n        for (int i = 0; i < Q; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(ans[i]);\n        }\n    }\n}\n"
