        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int N = sc.nextInt();\n\n        int[] keys = new int[N];\n        for (int i = 0; i < N; i++) {\n            keys[i] = sc.nextInt();\n        }\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        int[] positions = new int[N];\n        Arrays.fill(positions, -1);\n\n        for (int i = 0; i < N; i++) {\n            int x = keys[i];\n            int h = x % M;\n\n            for (int j = 0; j < M; j++) {\n                int idx = (h + j * j) % M;\n                if (table[idx] == -1) {\n                    table[idx] = x;\n                    positions[i] = idx;\n                    break;\n                }\n            }\n        }\n\n        for (int i = 0; i < N; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(positions[i]);\n        }\n        System.out.println();\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n    }\n}\n"
