        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] homes = new int[n];\n        for (int i = 0; i < n; i++) {\n            homes[i] = sc.nextInt();\n        }\n\n        boolean[] used = new boolean[M];\n        StringBuilder out = new StringBuilder();\n\n        for (int idx = 0; idx < n; idx++) {\n            int k = homes[idx];\n            int placed = -1;\n\n            for (int i = 0; i < M; i++) {\n                int pos = (k + i) % M;\n                if (!used[pos]) {\n                    used[pos] = true;\n                    placed = pos;\n                    break;\n                }\n            }\n\n            if (idx > 0) {\n                out.append(\" \");\n            }\n            out.append(placed);\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
