        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    static int hash(int x, int m) {\n        return ((x % m) + m) % m;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] insertKeys = new int[n];\n        for (int i = 0; i < n; i++) {\n            insertKeys[i] = sc.nextInt();\n        }\n\n        int q = sc.nextInt();\n        int[] queryKeys = new int[q];\n        for (int i = 0; i < q; i++) {\n            queryKeys[i] = sc.nextInt();\n        }\n\n        Integer[] table = new Integer[M];\n\n        for (int key : insertKeys) {\n            int h = hash(key, M);\n            boolean alreadyExists = false;\n            int emptyPos = -1;\n\n            for (int i = 0; i < M; i++) {\n                int pos = (h + i * i) % M;\n\n                if (table[pos] == null) {\n                    emptyPos = pos;\n                    break;\n                }\n\n                if (table[pos] == key) {\n                    alreadyExists = true;\n                    break;\n                }\n            }\n\n            if (!alreadyExists && emptyPos != -1) {\n                table[emptyPos] = key;\n            }\n        }\n\n        StringBuilder out = new StringBuilder();\n\n        for (int idx = 0; idx < q; idx++) {\n            int key = queryKeys[idx];\n            int h = hash(key, M);\n            int found = -1;\n\n            for (int i = 0; i < M; i++) {\n                int pos = (h + i * i) % M;\n\n                if (table[pos] == null) {\n                    break;\n                }\n\n                if (table[pos] == key) {\n                    found = pos;\n                    break;\n                }\n            }\n\n            if (idx > 0) {\n                out.append(\" \");\n            }\n            out.append(found);\n        }\n\n        System.out.print(out.toString());\n    }\n}\n"
