        "content": "import java.util.*;\n\npublic class Main {\n    static int insert(int[] table, int key) {\n        int m = table.length;\n        int h = key % m;\n        if (h < 0) h += m;\n\n        for (int i = 0; i < m; i++) {\n            int pos = (h + i) % m;\n            if (table[pos] == -1) {\n                table[pos] = key;\n                return pos;\n            }\n        }\n        return -1;\n    }\n\n    static int search(int[] table, int key) {\n        int m = table.length;\n        int h = key % m;\n        if (h < 0) h += m;\n\n        for (int i = 0; i < m; i++) {\n            int pos = (h + i) % m;\n            if (table[pos] == -1) {\n                return -1;\n            }\n            if (table[pos] == key) {\n                return pos;\n            }\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int M = sc.nextInt();\n        int n = sc.nextInt();\n\n        int[] table = new int[M];\n        Arrays.fill(table, -1);\n\n        for (int i = 0; i < n; i++) {\n            int key = sc.nextInt();\n            insert(table, key);\n        }\n\n        int q = sc.nextInt();\n        int[] queries = new int[q];\n        for (int i = 0; i < q; i++) {\n            queries[i] = sc.nextInt();\n        }\n\n        for (int i = 0; i < M; i++) {\n            if (i > 0) System.out.print(\" \");\n            System.out.print(table[i]);\n        }\n        System.out.println();\n\n        for (int key : queries) {\n            System.out.println(search(table, key));\n        }\n    }\n}\n"
