        "filename": "Main.java",
        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int M = sc.nextInt();\n        int[] table = new int[M];\n        for (int i = 0; i < M; i++) {\n            table[i] = sc.nextInt();\n        }\n\n        int h = sc.nextInt();\n        int k = sc.nextInt();\n        int[] offsets = new int[k];\n        for (int i = 0; i < k; i++) {\n            offsets[i] = sc.nextInt();\n        }\n\n        if (table[h] == -1) {\n            System.out.println(h);\n            return;\n        }\n\n        for (int i = 0; i < k; i++) {\n            int pos = (h + offsets[i]) % M;\n            if (table[pos] == -1) {\n                System.out.println(pos);\n                return;\n            }\n        }\n\n        System.out.println(-1);\n    }\n}\n"
      }
