        "content": "import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        int M = sc.nextInt();\n        int[] table = new int[M];\n        for (int i = 0; i < M; i++) {\n            table[i] = sc.nextInt();\n        }\n        int key = sc.nextInt();\n\n        int h = key % M;\n        if (h < 0) h += M;\n\n        if (table[h] == -1 || table[h] == key) {\n            System.out.println(h);\n            return;\n        }\n\n        for (int i = 1; i < M; i++) {\n            int pos = (h + i * i) % M;\n            if (table[pos] == -1 || table[pos] == key) {\n                System.out.println(pos);\n                return;\n            }\n        }\n\n        System.out.println(-1);\n    }\n}\n"
