        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Notice {\n    protected String message;\n\n    public Notice(String message) {\n        this.message = message;\n    }\n\n    public String format() {\n        return message;\n    }\n}\n\nclass RepeatedNotice extends Notice {\n    public RepeatedNotice(String message) {\n        super(message);\n    }\n\n    @Override\n    public String format() {\n        return message + \"-\" + message;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String message = sc.nextLine();\n\n        Notice first = new Notice(message);\n        Notice second = new RepeatedNotice(message);\n\n        System.out.println(first.format());\n        System.out.println(second.format());\n    }\n}\n"
      }
