        "content": "import java.util.*;\n\nclass Person {\n    private String name;\n    private int age;\n    private double height;\n\n    private int moveCount;\n    private int eatCount;\n    private int drinkCount;\n    private int sleepCount;\n\n    public Person(String name, int age, double height) {\n        this.name = name;\n        this.age = age;\n        this.height = height;\n        this.moveCount = 0;\n        this.eatCount = 0;\n        this.drinkCount = 0;\n        this.sleepCount = 0;\n    }\n\n    public void moving() {\n        moveCount++;\n    }\n\n    public void eating() {\n        eatCount++;\n    }\n\n    public void drinking() {\n        drinkCount++;\n    }\n\n    public void sleeping() {\n        sleepCount++;\n    }\n\n    public int getTotalActions() {\n        return moveCount + eatCount + drinkCount + sleepCount;\n    }\n\n    public String getSummary() {\n        return name + \"-\" + age + \"-\" + height + \"-\" + getTotalActions();\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String name = sc.next();\n        int age = sc.nextInt();\n        double height = sc.nextDouble();\n        int n = sc.nextInt();\n\n        Person p = new Person(name, age, height);\n\n        for (int i = 0; i < n; i++) {\n            String cmd = sc.next();\n            if (cmd.equals(\"move\")) {\n                p.moving();\n            } else if (cmd.equals(\"eat\")) {\n                p.eating();\n            } else if (cmd.equals(\"drink\")) {\n                p.drinking();\n            } else if (cmd.equals(\"sleep\")) {\n                p.sleeping();\n            }\n        }\n\n        System.out.println(p.getTotalActions());\n        System.out.println(p.getSummary());\n    }\n}\n"
