        "content": "import java.util.*;\n\nclass CodeComparison {\n    private int proceduralLines;\n    private int oopLines;\n\n    public CodeComparison(int proceduralLines, int oopLines) {\n        this.proceduralLines = proceduralLines;\n        this.oopLines = oopLines;\n    }\n\n    public int getExtraLines() {\n        return oopLines - proceduralLines;\n    }\n\n    public boolean isOopLarger() {\n        return oopLines > proceduralLines;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int proceduralLines = sc.nextInt();\n        int oopLines = sc.nextInt();\n\n        CodeComparison comparison = new CodeComparison(proceduralLines, oopLines);\n        System.out.println(comparison.getExtraLines());\n        System.out.println(comparison.isOopLarger());\n    }\n}\n"
