        "content": "#include <stdio.h>\n\nint main(void) {\n    char ch;\n    int n;\n    float f;\n    double d;\n\n    scanf(\" %c %d %f %lf\", &ch, &n, &f, &d);\n\n    return 0;\n}\n",
        "is_readonly": false
