    "solution_code": [
      {
        "filename": "main.c",
        "content": "#include <stdio.h>\n\nint main(void) {\n    char ch;\n    int n;\n    float f;\n    double d;\n\n    scanf(\" %c %d %f %lf\", &ch, &n, &f, &d);\n\n    printf(\"Integral: %c %d\\n\", ch, n);\n    printf(\"Floating-point: %.2f %.2lf\\n\", f, d);\n\n    return 0;\n}\n"
      }
