        "content": "#include <stdio.h>\n\nint main(void) {\n    int n;\n    int i;\n    scanf(\"%d\", &n);\n\n    for (i = 7; i >= 0; i--) {\n        printf(\"%d\", (n >> i) & 1);\n    }\n    printf(\"\\n\");\n\n    return 0;\n}"
