        "content": "#include <stdio.h>\n\nint main(void) {\n    int a, b;\n    int common;\n\n    scanf(\"%d %d\", &a, &b);\n    common = a & b;\n\n    printf(\"%d\\n\", common);\n    if (common != 0) {\n        printf(\"COMMON\\n\");\n    } else {\n        printf(\"NONE\\n\");\n    }\n\n    return 0;\n}\n"
