        "content": "import java.util.*;\n\nclass Person {\n    protected String name;\n    protected String address;\n    protected String birthDate;\n\n    public Person(String name, String address, String birthDate) {\n        this.name = name;\n        this.address = address;\n        this.birthDate = birthDate;\n    }\n\n    public String getProfile() {\n        return \"\";\n    }\n}\n\nclass Student extends Person {\n    private String studentId;\n\n    public Student(String name, String address, String birthDate, String studentId) {\n        super(name, address, birthDate);\n        this.studentId = studentId;\n    }\n\n    @Override\n    public String getProfile() {\n        return \"\";\n    }\n}\n\nclass Professor extends Person {\n    private String department;\n\n    public Professor(String name, String address, String birthDate, String department) {\n        super(name, address, birthDate);\n        this.department = department;\n    }\n\n    @Override\n    public String getProfile() {\n        return \"\";\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        String studentName = sc.nextLine();\n        String studentAddress = sc.nextLine();\n        String studentBirthDate = sc.nextLine();\n        String studentId = sc.nextLine();\n\n        String professorName = sc.nextLine();\n        String professorAddress = sc.nextLine();\n        String professorBirthDate = sc.nextLine();\n        String department = sc.nextLine();\n\n        Person p1 = new Student(studentName, studentAddress, studentBirthDate, studentId);\n        Person p2 = new Professor(professorName, professorAddress, professorBirthDate, department);\n\n        System.out.println(p1.getProfile());\n        System.out.println(p2.getProfile());\n    }\n}\n",
