        "filename": "Main.java",
        "content": "import java.util.*;\n\nclass Person {\n    protected String name;\n    protected String address;\n    protected String birthDate;\n\n    public Person(String name, String address, String birthDate) {\n        this.name = name;\n        this.address = address;\n        this.birthDate = birthDate;\n    }\n\n    public String buildBadge() {\n        return name + \" | \" + address + \" | \" + birthDate;\n    }\n}\n\nclass Professor extends Person {\n    private String department;\n\n    public Professor(String name, String address, String birthDate, String department) {\n        super(name, address, birthDate);\n        this.department = department;\n    }\n\n    @Override\n    public String buildBadge() {\n        return super.buildBadge() + \" | \" + department;\n    }\n}\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String name = sc.nextLine();\n        String address = sc.nextLine();\n        String birthDate = sc.nextLine();\n        String department = sc.nextLine();\n\n        Professor professor = new Professor(name, address, birthDate, department);\n        System.out.print(professor.buildBadge());\n    }\n}\n"
